/* Flash cards USMLE: Cardiovascular (681 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["cardiovascular"] = [{"name":"Anatomy","cards":[["1848fhu7l","Which chamber forms most of the anterior surface of the heart?","Right ventricle.","Ventrículo direito."],["1swpm4o1y","Which chamber forms most of the left border of the heart?","Left ventricle.","Ventrículo esquerdo."],["1b4b83p22","Which chamber is the most posterior part of the heart?","Left atrium.","Átrio esquerdo."],["y7r2q512j","Why can an enlarged left atrium cause dysphagia or hoarseness?","It can compress the esophagus (dysphagia) or the left recurrent laryngeal nerve (hoarseness, Ortner syndrome).","Comprime esôfago e nervo laríngeo."],["1warvuy1t","What imaging study best shows the left atrium's relationship to the esophagus?","Transesophageal echocardiography (TEE), which is useful for detecting left atrial thrombi and atrial appendage clots.","Ecocardiograma transesofágico."],["19od0y2la","What does the right coronary artery (RCA) supply?","Right ventricle (via acute marginal artery), SA node (in most), AV node (in right-dominant), inferior portion of left ventricle and posterior septum (via PDA).","Lado direito e parede inferior."],["mrlf0bdru","What does the left anterior descending artery (LAD) supply?","Anterior two-thirds of the interventricular septum, anterolateral papillary muscle, anterior surface of the left ventricle.","Parede anterior e septo."],["8bptqx6uw","Which artery is most commonly occluded in MI?","Left anterior descending artery (LAD).","DA anterior."],["1n6nd4n1s","What does the left circumflex artery (LCX) supply?","Lateral and posterior walls of the left ventricle and the anterolateral papillary muscle.","Parede lateral."],["ehz5rnz4c","What determines coronary dominance?","The artery that supplies the posterior descending artery (PDA).","Quem dá a descendente posterior."],["37bakurpo","What percentage of people are right dominant?","About 85% (PDA from RCA); 8% left dominant (PDA from LCX); 7% codominant.","85%."],["yla14db17","Which papillary muscle is supplied by a single artery and is more prone to rupture?","Posteromedial papillary muscle (supplied only by the PDA).","Papilar posteromedial."],["15m2mjggp","When does coronary blood flow peak in the left ventricle?","In early diastole (when the myocardium relaxes).","Na diástole."],["1kcu0b815","Where does most coronary venous blood drain?","Into the coronary sinus, which runs in the left atrioventricular groove and drains into the right atrium.","Seio coronário."],["gi4316pyf","What does a dilated coronary sinus suggest?","Pulmonary hypertension (increased right heart pressure) or persistent left superior vena cava.","Hipertensão pulmonar."],["1fogi0h1x","Which artery supplies the SA node in most people?","Right coronary artery (about 60%).","Coronária direita."],["1d0npfywv","Which artery supplies the AV node in a right-dominant heart?","Right coronary artery (via the AV nodal branch, usually from the PDA region).","Coronária direita."],["1j5xql53a","Why does an inferior wall MI often cause bradycardia?","RCA occlusion can involve the AV nodal or SA nodal arteries, causing heart block or sinus bradycardia.","Isquemia do nó AV."],["1kqaygikp","Which ECG leads reflect the anterior wall of the left ventricle?","V1-V4 (anteroseptal V1-V2, anterior V3-V4).","V1 a V4."],["jdtlve8da","Which ECG leads reflect the lateral wall?","I, aVL, V5, V6 (LCX).","I, aVL, V5, V6."],["i9tvi31vx","Which ECG leads reflect the inferior wall?","II, III, aVF (RCA).","II, III, aVF."],["1cz6lclz2","What layers make up the pericardium?","Fibrous pericardium, parietal layer, and visceral layer (epicardium) of serous pericardium.","Fibroso, parietal, visceral."],["14a7wq1tb","Which nerve innervates the pericardium and causes referred shoulder pain in pericarditis?","Phrenic nerve (C3-C5).","Frênico."],["lsjcdcf4w","Which vessels form the transverse pericardial sinus?","It lies posterior to the aorta and pulmonary trunk and anterior to the SVC; surgeons use it to clamp great vessels.","Entre aorta/pulmonar e veias cavas."],["1v13kbagl","What is the oblique pericardial sinus?","A cul-de-sac posterior to the left atrium, bounded by the pulmonary veins and IVC.","Recesso atrás do átrio esquerdo."],["1cog0fpqt","Which structure separates the right atrium's smooth and rough parts?","Crista terminalis (internally) and sulcus terminalis (externally).","Crista terminal."],["336s6topv","What is the fossa ovalis?","Depression in the interatrial septum; remnant of the foramen ovale.","Resquício do forame oval."],["1leg5mp5e","What are pectinate muscles?","Muscular ridges in the right atrium and both auricles (derived from the primitive atrium).","Músculos do átrio."],["1uyow7aiy","What are trabeculae carneae?","Muscular ridges on the inner walls of the ventricles.","Trabéculas do ventrículo."],["15mgrljqd","What is the moderator band (septomarginal trabecula)?","Muscular band in the right ventricle carrying the right bundle branch to the anterior papillary muscle.","Ramo direito no VD."],["1pb2bpn17","Which valves are atrioventricular valves?","Tricuspid (right) and mitral (left) valves.","Mitral e tricúspide."],["apcwb2xdd","How many cusps does the mitral valve have?","Two (anterior and posterior).","Duas."],["10l40idhg","What anchors the AV valve leaflets to the ventricles?","Chordae tendineae attached to papillary muscles.","Cordas tendíneas."],["e51eir3h1","Where is the aortic valve best auscultated?","Right second intercostal space at the right sternal border.","2º espaço à direita."],["bbo9ce11c","Where is the pulmonic valve best auscultated?","Left second intercostal space at the left sternal border.","2º espaço à esquerda."],["9omwvqo0q","Where is the tricuspid valve best auscultated?","Left lower sternal border (4th-5th intercostal space).","Borda esternal esquerda baixa."],["17lclzidx","Where is the mitral valve best auscultated?","Cardiac apex (left 5th intercostal space at the midclavicular line).","Ápice."],["1mazr2f1n","What is the conduction pathway of the heart?","SA node, atria, AV node, bundle of His, right and left bundle branches, Purkinje fibers, ventricles.","SA, AV, His, ramos, Purkinje."],["1q5bwoils","Where is the SA node located?","In the wall of the right atrium near the opening of the superior vena cava.","Átrio direito, junto à cava."],["yt3z931fv","Where is the AV node located?","In the posteroinferior interatrial septum near the opening of the coronary sinus (triangle of Koch).","Septo interatrial."],["1ci5bks1j","Which conduction tissue has the fastest conduction velocity?","Purkinje fibers (fastest), then atria, ventricles, AV node (slowest). Park At Venture Avenue.","Purkinje."],["cpn7891yd","Why does the AV node conduct slowly?","Allows time for ventricular filling before contraction.","Permite encher ventrículos."],["760kln1al","What is the intrinsic pacemaker rate of the SA node?","About 60-100 bpm (dominant pacemaker).","60-100."],["zsmquueh1","What are the intrinsic rates of the AV node and ventricles?","AV node about 40-60 bpm; ventricles (Purkinje) about 20-40 bpm.","40-60 e 20-40."],["hfd0eu1jp","Which nerve supplies parasympathetic innervation to the heart?","Vagus nerve (right vagus mainly to SA node, left vagus mainly to AV node).","Vago."],["1enn88v1a","Where do cardiac sympathetic fibers originate?","T1-T4 spinal segments via cervical and upper thoracic sympathetic ganglia.","T1-T4."],["704px5177","Why is cardiac ischemic pain referred to the left arm and jaw?","Visceral afferents travel with sympathetic fibers to T1-T4, sharing segments with somatic afferents of the arm and chest.","Mesmos segmentos espinhais."],["1of0htre0","Which structures pass through the aortic hiatus of the diaphragm?","Aorta, thoracic duct, azygos vein (T12).","Aorta, ducto torácico, ázigos."],["15xy3afoc","Which structure passes through the caval opening of the diaphragm?","Inferior vena cava (T8), with branches of the right phrenic nerve.","Veia cava inferior."],["661o331s4","Which structures pass through the esophageal hiatus?","Esophagus and vagal trunks (T10).","Esôfago e vagos."],["1u4npt71s","Mnemonic for diaphragm openings?","I (IVC) 8 10 Eggs (Esophagus) At 12 (Aorta).","I ate 10 eggs at 12."],["w08xix175","What are the three branches of the aortic arch?","Brachiocephalic trunk, left common carotid artery, left subclavian artery.","Braquiocefálica, carótida e subclávia esquerdas."],["m4ee0j1qf","Which artery supplies the right arm and right head/neck?","Brachiocephalic trunk (divides into right subclavian and right common carotid).","Braquiocefálica."],["1mk9xzn1h","What structure connects the aortic arch to the pulmonary artery in adults?","Ligamentum arteriosum (remnant of ductus arteriosus).","Ligamento arterioso."],["1v4r4rwyd","Which nerve loops around the ligamentum arteriosum?","Left recurrent laryngeal nerve.","Laríngeo recorrente esquerdo."],["mteqet82l","Where is the most common site of aortic coarctation in adults?","Just distal to the left subclavian artery near the ligamentum arteriosum (postductal).","Após a subclávia esquerda."],["93uemy19a","What is the most common site of traumatic aortic rupture?","Aortic isthmus (just distal to the origin of the left subclavian artery), where the mobile arch meets the fixed descending aorta.","Istmo aórtico."],["1fcc9gc1l","What layers make up the arterial wall?","Tunica intima (endothelium), tunica media (smooth muscle, elastic tissue), tunica adventitia (connective tissue, vasa vasorum).","Íntima, média, adventícia."],["qxn0k614u","Which vessels contribute most to total peripheral resistance?","Arterioles.","Arteríolas."],["1a8seg91c","Which vessels have the largest total cross-sectional area and slowest flow?","Capillaries.","Capilares."],["1m2rt4031","Which vessels contain the most blood volume?","Veins (capacitance vessels).","Veias."]]},{"name":"Pathology (Part 1)","cards":[["1i6sgw21h","Which congenital heart defects cause early cyanosis (right-to-left shunts)?","The 5 Ts: Truncus arteriosus, Transposition of the great vessels, Tricuspid atresia, Tetralogy of Fallot, Total anomalous pulmonary venous return.","Os 5 Ts."],["aa9gb71rt","Which congenital heart defects cause left-to-right shunts?","VSD (most common), ASD, PDA. Mnemonic: RIGHT-to-left = eaRLy cyanosis; LEFT-to-right = 'LateR' cyanosis.","CIV, CIA, PCA."],["6kjous1wz","What is persistent truncus arteriosus?","Failure of the truncus to divide into the pulmonary trunk and aorta due to lack of aorticopulmonary septum; most also have a VSD.","Um tronco só."],["1luvp7sm8","What is dextro-transposition of the great vessels?","Aorta leaves the RV (anterior) and pulmonary trunk leaves the LV (posterior), creating separate parallel circulations.","Aorta e pulmonar trocadas."],["8a7yq81pl","Why is D-transposition incompatible with life without a shunt?","Systemic and pulmonary circulations are separate; survival requires a VSD, PDA, or patent foramen ovale.","Circulações separadas."],["18syld99m","Embryologic cause of transposition of the great vessels?","Failure of the aorticopulmonary septum to spiral.","Septo não espirala."],["vkgw9bkv9","Which maternal condition is associated with transposition of the great vessels?","Maternal diabetes.","Diabetes materno."],["1c2qng644","Initial treatment of transposition of the great vessels?","Prostaglandin E1 to keep the ductus arteriosus open, then surgical arterial switch.","Prostaglandina e cirurgia."],["17ipj501a","What is tricuspid atresia?","Absence of tricuspid valve and hypoplastic RV; requires both ASD and VSD for survival.","Tricúspide ausente."],["ijvz6i869","What are the four components of tetralogy of Fallot?","Pulmonary infundibular stenosis (most important for prognosis), RV hypertrophy (boot-shaped heart), overriding aorta, VSD. Mnemonic: PROVe.","Estenose pulmonar, HVD, aorta cavalgante, CIV."],["mezsdoeqz","Embryologic cause of tetralogy of Fallot?","Anterosuperior displacement of the infundibular septum.","Septo infundibular desviado."],["16k9l1h1l","What are 'tet spells' and how do children relieve them?","Cyanotic episodes; squatting increases SVR, decreasing the right-to-left shunt and improving cyanosis.","Crise de cianose; agachar."],["1wd7uuo1n","Chest x-ray finding in tetralogy of Fallot?","Boot-shaped heart (RV hypertrophy).","Coração em bota."],["vamv74165","What is total anomalous pulmonary venous return?","Pulmonary veins drain into the right heart circulation (SVC, coronary sinus); associated with ASD and sometimes PDA.","Veias pulmonares no lado direito."],["1hx66mpm6","What is Ebstein anomaly?","Displacement of tricuspid valve leaflets downward into the RV, atrializing part of it; associated with tricuspid regurgitation, accessory pathways, and RHF.","Tricúspide deslocada."],["87935vmlr","Which drug exposure is associated with Ebstein anomaly?","Lithium exposure in utero.","Lítio."],["10urofj1d","What is the most common congenital cardiac defect?","Ventricular septal defect (VSD).","CIV."],["1f0jx0jhx","Which VSDs close spontaneously?","Many small muscular VSDs close spontaneously; larger lesions may lead to LV overload and heart failure.","Pequenas e musculares."],["mlz9zm11g","Which type of ASD is most common?","Ostium secundum defect.","Ostium secundum."],["47qgwukzp","Which ASD is associated with Down syndrome?","Ostium primum defect (part of AV septal defects).","Ostium primum."],["tls2gs1ci","What is the auscultation finding in an ASD?","Loud S1 and wide, fixed split S2; may have pulmonary flow murmur.","Desdobramento fixo de B2."],["oou9q4ag4","What is the risk of an ASD in adults?","Paradoxical emboli (venous thrombus crossing to systemic circulation), right heart overload.","Embolia paradoxal."],["1i39kno3g","How does a patent foramen ovale differ from an ASD?","PFO is due to failure of septum primum and secundum to fuse; there is no missing tissue. Usually asymptomatic but can allow paradoxical emboli.","Sem falta de tecido."],["ile9ebffi","What is patent ductus arteriosus?","Persistence of the ductus arteriosus connecting the pulmonary artery to the aorta; initially left-to-right shunt.","Ducto aberto."],["1jqc20tma","Which infection in pregnancy is associated with PDA?","Congenital rubella.","Rubéola."],["mzvotu9h4","Which drug closes a PDA?","Indomethacin or ibuprofen (NSAIDs inhibit prostaglandin E2); acetaminophen may also be used.","Indometacina."],["1waebnv1v","Which drug keeps a PDA open?","Prostaglandin E1 (alprostadil).","Prostaglandina E1."],["cg1ov1f0r","What is Eisenmenger syndrome?","Uncorrected left-to-right shunt leads to pulmonary hypertension and RV hypertrophy, reversing the shunt to right-to-left, causing late cyanosis, clubbing, polycythemia.","Shunt inverte."],["1dkpfre1a","What is differential cyanosis in PDA with Eisenmenger?","Cyanosis and clubbing of the lower extremities but not upper extremities (shunt enters aorta distal to the left subclavian).","Cianose nos pés."],["tiu1wm107","What is coarctation of the aorta?","Narrowing of the aorta, most often near the ductus arteriosus (juxtaductal).","Estreitamento da aorta."],["1nt4tz1os","Clinical features of coarctation of the aorta?","Hypertension in upper extremities, weak delayed femoral pulses (brachiofemoral delay), lower extremity claudication.","Pressão alta nos braços."],["185ckok1w","Imaging signs of coarctation in older children/adults?","Notching of ribs (collateral intercostal arteries), figure 3 sign on chest x-ray.","Erosão de costelas, sinal do 3."],["a9iapb1ge","Which conditions are associated with coarctation of the aorta?","Turner syndrome, bicuspid aortic valve, cerebral berry aneurysms.","Turner e valva bicúspide."],["1ewd05w10","Which congenital heart defects are associated with 22q11 deletion?","Truncus arteriosus and tetralogy of Fallot (conotruncal anomalies).","Truncus e tetralogia."],["mu3ot21wt","Which congenital heart defects are associated with Down syndrome?","AV septal defect (endocardial cushion), VSD, ASD.","Defeito do septo AV."],["5i9jny86m","Which congenital heart defects are associated with Turner syndrome?","Bicuspid aortic valve, coarctation of the aorta.","Coarctação e valva bicúspide."],["deq48qy13","Which defects are associated with congenital rubella?","PDA, pulmonary artery stenosis, septal defects.","PCA e estenose pulmonar."],["1hht5rs1m","Which defect is associated with Marfan syndrome?","Mitral valve prolapse, thoracic aortic aneurysm and dissection, aortic regurgitation.","Aneurisma de aorta."],["11yvbk7l2","Which defect is associated with Williams syndrome?","Supravalvular aortic stenosis.","Estenose aórtica supravalvar."],["xke9edsht","Which defect is associated with infant of diabetic mother?","Transposition of the great vessels, VSD, hypertrophic cardiomyopathy (transient).","Transposição."],["1h869g71n","Which defect is associated with Friedreich ataxia?","Hypertrophic cardiomyopathy.","Cardiomiopatia hipertrófica."],["nk6u7c5hf","Definition of hypertension in adults?","Persistent systolic BP ≥130 mmHg and/or diastolic BP ≥80 mmHg (ACC/AHA).","130/80 ou mais."],["5gv3ges2n","What proportion of hypertension is primary (essential)?","About 90%; related to increased cardiac output or TPR.","90-95%."],["1h5jvsvgl","Name causes of secondary hypertension.","Renal parenchymal disease, renal artery stenosis (atherosclerosis or fibromuscular dysplasia), primary hyperaldosteronism, Cushing, pheochromocytoma, coarctation, OSA, drugs.","Rim, adrenal, coarctação."],["arjufk198","What is fibromuscular dysplasia?","Nonatherosclerotic disease of medium arteries, often in young women; string of beads appearance on angiography; causes renovascular hypertension.","Artéria em colar de contas."],["9dh88z19v","What is hypertensive emergency?","Severe hypertension (usually >180/120) with evidence of acute end-organ damage (encephalopathy, stroke, MI, aortic dissection, AKI, pulmonary edema, papilledema).","Pressão alta com lesão de órgão."],["je1n0q1ri","Complications of chronic hypertension?","Cardiac hypertrophy, heart failure, atherosclerosis, stroke, CKD (hypertensive nephropathy), retinopathy, aortic dissection.","AVC, IAM, insuficiência renal."],["q7mli11xw","Histologic change in benign hypertensive arterioles?","Hyaline arteriolosclerosis: thickened, pink, glassy arteriolar walls.","Arteriolosclerose hialina."],["1wje28p8e","Histologic change in malignant hypertension arterioles?","Hyperplastic arteriolosclerosis: onion skin appearance with fibrinoid necrosis.","Casca de cebola."],["1lqkyg8ma","Where does hyaline arteriolosclerosis also occur besides hypertension?","Diabetes mellitus (nonenzymatic glycosylation).","Diabetes."],["mvvfwsxfd","What is Mönckeberg (medial calcific) sclerosis?","Calcification of the media of medium arteries (radial, ulnar); pipestem on x-ray; does not obstruct blood flow.","Calcificação da média."],["ht7ek1er8","What are signs of hyperlipidemia on exam?","Xanthomas (eyelids = xanthelasma, tendons), corneal arcus.","Xantomas e arco corneano."],["1iu9rco1l","Earliest lesion of atherosclerosis?","Fatty streak (lipid-laden macrophages/foam cells in intima).","Estria gordurosa."],["15kpr06ui","Steps in atherosclerosis pathogenesis?","Endothelial dysfunction, macrophage and LDL accumulation, foam cell formation, fatty streaks, smooth muscle migration, fibrous plaque, complex atheroma.","Lesão endotelial, LDL, macrófagos."],["1rukrak73","Which growth factor drives smooth muscle proliferation in atherosclerosis?","PDGF and FGF.","PDGF."],["oj5r32nc8","Modifiable risk factors for atherosclerosis?","Smoking, hypertension, dyslipidemia (high LDL), diabetes.","Fumo, hipertensão, diabetes, LDL."],["c3nchdbkg","Nonmodifiable risk factors for atherosclerosis?","Age, male sex, postmenopausal status, family history.","Idade, sexo, história familiar."],["ffugusbja","Most common locations of atherosclerosis in order?","Abdominal aorta > coronary arteries > popliteal arteries > carotid arteries > circle of Willis.","Aorta abdominal, coronária, poplítea, carótida."],["1ca59ui1e","Which plaque types are prone to rupture?","Plaques with large lipid core, thin fibrous cap, and many inflammatory cells (vulnerable plaque).","Placa com capa fina."],["1crjxuq1h","Complications of atherosclerosis?","Aneurysms, ischemia, infarcts, peripheral vascular disease, thrombus, emboli.","Isquemia, aneurisma, trombose."],["a4b1eq1om","What is an abdominal aortic aneurysm?","Localized dilation of the abdominal aorta (>3 cm), usually infrarenal, associated with atherosclerosis.","Dilatação da aorta abdominal."],["1pzm9h71b","Risk factors for abdominal aortic aneurysm?","Smoking (strongest), male sex, age >65, family history, hypertension.","Fumo, idade, homem."],["1y2b713en","Who should be screened for AAA?","Men 65-75 who have ever smoked (one-time abdominal ultrasound).","Homem 65-75 que fumou."],["19kr1ggvp","Presentation of a ruptured AAA?","Severe abdominal/back pain, pulsatile abdominal mass, hypotension (triad).","Dor, hipotensão, massa pulsátil."],["281pgitq1","What causes a thoracic aortic aneurysm?","Cystic medial degeneration; associated with hypertension, bicuspid aortic valve, connective tissue disease (Marfan), and historically tertiary syphilis (obliterative endarteritis of vasa vasorum).","Necrose cística da média."],["1m10stb1r","What is aortic dissection?","Longitudinal intimal tear forming a false lumen in the media.","Rasgo na íntima."],["1qigxjd1t","Risk factors for aortic dissection?","Hypertension (most common), bicuspid aortic valve, connective tissue diseases (Marfan, Ehlers-Danlos), cocaine, prior cardiac surgery.","Hipertensão, Marfan."],["yyn3io184","Presentation of aortic dissection?","Tearing, sudden-onset chest pain radiating to the back, unequal blood pressures in arms, mediastinal widening on chest x-ray.","Dor rasgando nas costas."],["1woi2me11","Which complications can aortic dissection cause?","Organ ischemia, aortic rupture, cardiac tamponade, aortic regurgitation, MI (if coronary arteries involved), stroke.","Tamponamento, AVC, isquemia."],["1c4b2hq1n","Stanford type A vs type B aortic dissection?","Type A: involves ascending aorta; requires surgery. Type B: involves descending aorta only (distal to left subclavian); medical management (beta-blockers, BP control).","Ascendente vs descendente."],["agoqzm1tf","Initial medical therapy for aortic dissection?","IV beta-blocker (esmolol, labetalol) to lower heart rate and BP, then vasodilators if needed; pain control.","Betabloqueador."],["5xaoy1jee","What is stable angina?","Chest pain from fixed coronary stenosis (usually >70%) with exertion or stress, relieved by rest or nitroglycerin; ST depression.","Dor no esforço."],["vqbuq7hf0","What is Prinzmetal (vasospastic) angina?","Chest pain at rest due to coronary vasospasm; transient ST elevation; triggers include tobacco, cocaine, triptans.","Espasmo coronário."],["1nt5f8d1u","Treatment of vasospastic angina?","Calcium channel blockers and nitrates; smoking cessation; avoid nonselective beta-blockers.","Bloqueador de cálcio."],["99koky11a","What is unstable angina?","Chest pain at rest or with increasing frequency due to thrombosis with incomplete coronary occlusion; troponins normal.","Dor em repouso."],["ydybaal0m","What is NSTEMI?","Subendocardial infarction with elevated troponin and ST depression or T wave changes.","IAM sem supra."],["lto5o2k1s","What is STEMI?","Transmural infarction with ST elevation and elevated troponins, often from complete occlusion.","IAM com supra."],["po0cx11tf","What is coronary steal syndrome?","Vasodilators (dipyridamole, regadenoson) dilate normal vessels, shunting blood away from stenotic areas, worsening ischemia; used in pharmacologic stress testing.","Vasodilatador desvia fluxo."],["n1785z187","Which part of the myocardium is most vulnerable to ischemia?","Subendocardium (furthest from epicardial coronary vessels, highest wall stress).","Subendocárdio."],["n5gqsd11s","What is the most common cause of sudden cardiac death?","Lethal arrhythmia (ventricular fibrillation), usually due to coronary artery disease.","Arritmia."],["ii458ewjo","Which cardiac biomarker is most specific for MI?","Cardiac troponin I (or T); rises 2-4 hours after infarction, peaks at 24 hours, remains elevated up to 10 days.","Troponina."],["q3z41tm7j","Which biomarker is useful for detecting reinfarction?","CK-MB (returns to normal by 48 hours).","CK-MB."],["87k3kzji7","ECG evolution in STEMI?","Hyperacute T waves, ST elevation, Q waves (days), T wave inversion.","Supra, Q, T invertida."],["1cjtiotzm","What is the earliest gross change in MI?","None visible in the first 0-4 hours; dark mottling appears at 4-24 hours.","Nenhuma."],["10ith0k73","Histologic changes 4-24 hours after MI?","Coagulative necrosis begins, early neutrophil infiltration, contraction bands with reperfusion, wavy fibers.","Necrose inicial."],["1qol31kto","Histologic changes 1-3 days after MI?","Extensive coagulative necrosis with neutrophil infiltration (acute inflammation).","Neutrófilos."],["1g4000x1l","Which complication peaks 1-3 days after MI?","Postinfarction fibrinous pericarditis.","Pericardite."],["7e44po6l7","Histologic changes 3-14 days after MI?","Macrophages remove necrotic tissue, granulation tissue forms at the margins (yellow then red-gray border).","Macrófagos."],["1jqt2np1a","Which complications peak 3-14 days after MI?","Free wall rupture (tamponade), papillary muscle rupture (mitral regurgitation), interventricular septal rupture, LV pseudoaneurysm.","Rupturas."],["7estgxoyl","Why are the 3-14 day post-MI complications common?","The infarcted wall is weakest, as macrophages clear debris before collagen forms.","Tecido amolecido."],["nqlvxzdvo","Histologic changes 2 weeks to several months after MI?","Contracted gray-white scar (collagen).","Cicatriz."],["yv1xa9r3a","Which complications occur weeks to months after MI?","Dressler syndrome (autoimmune pericarditis), heart failure, arrhythmias, true ventricular aneurysm (mural thrombus risk).","Aneurisma e Dressler."],["16zvtc41n","What is the most common cause of death in the first days after MI?","Arrhythmia (ventricular fibrillation).","Arritmia."],["dxqu0ebg6","What does papillary muscle rupture after MI cause?","Acute severe mitral regurgitation with sudden pulmonary edema; usually posteromedial papillary muscle (PDA from RCA).","Regurgitação mitral."],["1hgxky5g8","What does interventricular septal rupture cause?","Acute left-to-right shunt with a new holosystolic murmur and increased O2 saturation in the right ventricle (step-up).","Shunt esquerda-direita."],["1cger6712","What does free wall rupture cause?","Cardiac tamponade (hypotension, JVD, muffled heart sounds) with sudden death.","Tamponamento."],["1iurncctv","What is a true ventricular aneurysm?","Outward bulge of thin scar tissue weeks after MI; risk of mural thrombus, arrhythmia, heart failure; persistent ST elevation.","Parede fina que abaula."],["1yk6v951k","What is a pseudoaneurysm after MI?","Free wall rupture contained by pericardium/scar; narrow neck; high risk of rupture.","Ruptura contida."],["3by7hzpyv","What is Dressler syndrome?","Autoimmune fibrinous pericarditis weeks after MI or cardiac surgery, from antibodies to myocardial antigens.","Pericardite autoimune."],["86rjqy1gx","Right ventricular infarction findings?","Hypotension, elevated JVP, clear lungs; occurs with inferior MI (RCA); avoid nitrates; treat with IV fluids.","Hipotensão, JVP alta, pulmão limpo."],["1o990qodn","Immediate treatment of STEMI?","Aspirin, P2Y12 inhibitor, anticoagulant (heparin), nitroglycerin, beta-blockers (if no shock), oxygen if hypoxemic; reperfusion with PCI (or fibrinolysis).","Reperfusão rápida."],["11kry9c4s","Long-term therapy after MI?","Aspirin plus P2Y12 inhibitor (DAPT), beta-blocker, ACE inhibitor or ARB, high-intensity statin; aldosterone antagonist if reduced EF.","Aspirina, estatina, betabloqueador, IECA."],["lfvuz0utq","Which post-MI drugs reduce mortality?","Aspirin, beta-blockers, ACE inhibitors/ARBs, statins, aldosterone antagonists (if EF reduced).","Betabloqueador, IECA, estatina."],["2mp4gwz2c","Why is nitroglycerin contraindicated with PDE5 inhibitors?","Risk of severe hypotension.","Hipotensão grave."],["8uee3o9y7","What are signs of reperfusion injury?","Arrhythmias and contraction band necrosis due to Ca2+ influx and free radicals.","Arritmias e hemorragia."],["11wlor7y4","What is myocardial stunning?","Temporary loss of contractility after reperfusion despite viable myocardium.","Disfunção temporária."],["pwebvf1s8","What is hibernating myocardium?","Chronically ischemic but viable myocardium with reduced function that improves after revascularization.","Adaptado à baixa perfusão."],["1a9pa4517","What is the classic presentation of acute limb ischemia?","Six Ps: pain, pallor, pulselessness, paresthesias, poikilothermia, paralysis.","6 Ps."],["knvsmq17n","What is peripheral artery disease's classic symptom?","Intermittent claudication (calf pain with walking relieved by rest).","Claudicação."],["usvjb4b45","What test diagnoses peripheral artery disease?","Ankle-brachial index <0.9.","Índice tornozelo-braço."],["1he6bbz1f","Treatment of claudication?","Exercise program, smoking cessation, antiplatelet therapy, statins; cilostazol for symptoms.","Exercício e cilostazol."],["1dh1xfu50","What is subclavian steal syndrome?","Stenosis of the subclavian artery proximal to the vertebral artery causes retrograde vertebral flow during arm exercise, leading to arm ischemia and vertebrobasilar insufficiency.","Fluxo reverso na vertebral."],["2ewlc3x2m","What is Leriche syndrome?","Aortoiliac occlusion: claudication of buttocks/thighs, absent femoral pulses, erectile dysfunction.","Claudicação glútea e impotência."],["san286160","What is cholesterol embolization syndrome?","Atheroembolism after vascular procedures: livedo reticularis, blue toes, AKI, eosinophilia, low complement.","Êmbolo de colesterol."],["87dzn52od","What is the most common cause of ischemic stroke from the heart?","Atrial fibrillation (left atrial appendage thrombus).","Fibrilação atrial."],["meamvo2xa","What are mural thrombi associated with?","MI (akinetic segments), ventricular aneurysm, dilated cardiomyopathy, atrial fibrillation.","IAM e cardiomiopatia."],["1n448jp4c","What is the most common primary cardiac tumor in adults?","Myxoma, usually in the left atrium.","Mixoma."],["1lfj11z12","Clinical features of atrial myxoma?","Ball-valve obstruction (syncope), tumor plop (early diastolic sound), constitutional symptoms (IL-6), emboli.","Síncope e plop tumoral."],["1udjj3h2k","What is the most common primary cardiac tumor in children?","Rhabdomyoma (associated with tuberous sclerosis).","Rabdomioma."],["upj1cf1el","What is the most common heart tumor overall?","Metastases (e.g., melanoma, lymphoma, lung, breast).","Metástase."],["pybvyq1lp","What is Kussmaul sign?","Paradoxical increase in JVP on inspiration; seen in constrictive pericarditis, restrictive cardiomyopathy, right heart failure, tamponade (rare).","Pressão venosa sobe na inspiração."],["1rdhxenfy","What is hypertrophic cardiomyopathy's most common cause of sudden death?","Ventricular arrhythmias, often in young athletes.","Arritmia ventricular."],["4vp77z1al","What congenital defect is often associated with a single umbilical artery?","Congenital and chromosomal anomalies, including cardiac and renal anomalies.","Anomalias renais e cardíacas."],["1pk81lc1t","What is hypoplastic left heart syndrome?","Underdevelopment of left heart structures (mitral, aortic valves, LV, aorta); systemic circulation depends on PDA; requires staged surgery.","VE subdesenvolvido."],["1hqdmuu14","Which congenital heart lesion presents with heart failure and shock when the ductus closes in the first week?","Ductal-dependent left heart obstructive lesions (hypoplastic left heart, critical coarctation, critical aortic stenosis).","Lesão dependente do ducto."],["sj0yup1vh","What does an egg on a string x-ray finding indicate?","Transposition of the great vessels.","Transposição."],["7ksswm8n8","What does a snowman sign on chest x-ray indicate?","Supracardiac total anomalous pulmonary venous return.","Retorno venoso anômalo."],["1hgr8d0bd","What is the most common cardiac lesion in congenital rubella besides PDA?","Pulmonary artery stenosis.","Estenose pulmonar."],["1t1d14ob5","What is the most common cause of death in patients with hypertension?","Cardiovascular disease (ischemic heart disease, heart failure) and stroke.","Doença cardíaca."],["1byv75pcm","What is the role of aspirin in primary prevention?","Considered selectively for higher-risk adults with low bleeding risk; routine use in older adults is not recommended.","Uso individualizado."],["1mv4fwclq","What is the role of statins in atherosclerotic disease?","Lower LDL, stabilize plaques, and reduce cardiovascular events and mortality.","Estabilizam placa."],["q564po1i7","What is the mechanism of plaque rupture causing MI?","Rupture exposes thrombogenic material leading to platelet aggregation and thrombus formation occluding the vessel.","Capa fina rompe."],["1i5tmq152","What is the typical presentation of MI in women, elderly, and diabetics?","Atypical symptoms: dyspnea, fatigue, nausea, epigastric pain; may be painless (silent) in diabetics due to neuropathy.","Sintomas atípicos."],["1da4ywa9y","What ECG finding suggests posterior wall MI?","ST depression in V1-V3 with tall R waves; confirm with posterior leads V7-V9.","Depressão ST em V1-V3."],["1lmgqnohh","What is a Q wave's significance on ECG after MI?","Indicates prior transmural infarction (necrotic myocardium).","Necrose transmural."],["1yzly1y1s","What is the most common cause of a new systolic murmur 3-5 days after MI with hypotension?","Papillary muscle rupture (acute mitral regurgitation) or ventricular septal rupture.","Ruptura papilar."],["56t1yoz31","What is the mechanism of cocaine-induced MI?","Coronary vasospasm, increased O2 demand (sympathomimetic), accelerated thrombosis.","Vasoespasmo."],["egz0t54ok","Treatment of cocaine-associated chest pain?","Benzodiazepines, aspirin, nitrates, calcium channel blockers; avoid beta-blockers acutely (classic teaching).","Benzodiazepínicos."],["1mev23miw","What is the most common type of aortic dissection location?","Ascending aorta (Stanford type A), often just above the aortic valve.","Aorta ascendente."],["1jvqopmte","What histologic change underlies aortic dissection in Marfan syndrome?","Cystic medial degeneration (loss of elastic fibers and smooth muscle with mucoid material).","Necrose cística da média."],["1nfmwza1r","What is an aortic intramural hematoma?","Bleeding within the aortic media without an intimal tear; managed like dissection.","Sangue na parede."],["1i7hyfypv","What is the risk factor most strongly associated with AAA expansion and rupture?","Smoking (and larger diameter; repair is recommended at ≥5.5 cm in men).","Fumo."]]},{"name":"Pathology (Part 2)","cards":[["19c6vy8bb","What is heart failure?","Clinical syndrome in which the heart cannot pump enough blood to meet metabolic needs, or does so only with elevated filling pressures.","Coração não supre a demanda."],["mx8ozd4wj","What is heart failure with reduced ejection fraction?","Systolic dysfunction with EF ≤40%; increased EDV; causes include ischemic heart disease, dilated cardiomyopathy, MI.","Fração de ejeção baixa."],["5eg3m1y0z","What is heart failure with preserved ejection fraction?","Diastolic dysfunction with normal EF, impaired relaxation/compliance; causes include hypertension, LV hypertrophy, aging, restrictive cardiomyopathy.","Fração de ejeção preservada."],["i5hvo06xy","Most common cause of right heart failure?","Left heart failure.","Insuficiência esquerda."],["v8xs9lbwi","What is cor pulmonale?","Right heart failure due to pulmonary disease or pulmonary hypertension.","IC direita por doença pulmonar."],["10or35u18","Signs of left heart failure?","Dyspnea, orthopnea, paroxysmal nocturnal dyspnea, pulmonary edema, crackles, S3.","Dispneia, ortopneia, estertores."],["1nkibll1f","Signs of right heart failure?","Increased JVP, hepatomegaly (nutmeg liver), peripheral edema, hepatojugular reflux, ascites.","Edema, turgência jugular, hepatomegalia."],["nypi491dt","What are heart failure cells?","Hemosiderin-laden macrophages in the lungs from extravasated RBCs in pulmonary congestion.","Macrófagos com hemossiderina."],["18cq7tp17","Why does orthopnea occur?","Lying flat increases venous return to an overloaded left heart, worsening pulmonary congestion.","Mais retorno venoso deitado."],["wf4apbib3","What is a nutmeg liver?","Chronic passive congestion of the liver from right heart failure (centrilobular congestion); can lead to cardiac cirrhosis.","Fígado congestionado."],["3q2x5xn9t","Which drugs reduce mortality in HFrEF?","ACE inhibitors/ARBs or ARNI (sacubitril-valsartan), beta-blockers (carvedilol, metoprolol succinate, bisoprolol), aldosterone antagonists, SGLT2 inhibitors, hydralazine with nitrate (in Black patients).","IECA, betabloqueador, espironolactona, SGLT2."],["1hcl3m21o","Which drugs improve symptoms but not mortality in HF?","Loop diuretics and digoxin.","Diuréticos e digoxina."],["66h4onk5j","Why are beta-blockers contraindicated in acute decompensated heart failure?","They reduce contractility acutely; started once the patient is stable (euvolemic).","Reduzem contratilidade."],["5grnci10h","What is the compensatory neurohormonal response in heart failure?","Activation of RAAS and sympathetic system, ADH release, causing fluid retention and vasoconstriction that worsens HF over time.","SRAA e simpático."],["jwg1lu1fs","What is dilated cardiomyopathy?","Most common cardiomyopathy; four-chamber dilation and systolic dysfunction (eccentric hypertrophy).","Ventrículo dilatado e fraco."],["1fx56tl1k","Causes of dilated cardiomyopathy?","Idiopathic/genetic (often autosomal dominant), alcohol, beriberi, Coxsackie B myocarditis, cocaine, Chagas, doxorubicin, hemochromatosis, peripartum, sarcoidosis, thyrotoxicosis.","Álcool, vírus, doxorrubicina."],["1wnf7j714","Findings in dilated cardiomyopathy?","Heart failure symptoms, S3, systolic regurgitant murmur (MR, TR), dilated heart on echo, balloon appearance on chest x-ray.","Coração grande, B3."],["g2vspi1u6","Which chemotherapy drugs cause dilated cardiomyopathy?","Anthracyclines (doxorubicin, daunorubicin) and trastuzumab.","Doxorrubicina e trastuzumabe."],["wxmkatzij","How can doxorubicin cardiotoxicity be prevented?","Dexrazoxane (iron chelator) and cumulative dose limits.","Dexrazoxano."],["htiq7uith","What is hypertrophic cardiomyopathy?","Asymmetric LV hypertrophy, often septal, with diastolic dysfunction; often autosomal dominant mutations in sarcomere genes (beta-myosin heavy chain, myosin-binding protein C).","Hipertrofia do septo."],["y7otljkvh","Histology of hypertrophic cardiomyopathy?","Myofiber disarray and fibrosis.","Fibras desorganizadas."],["tlqndv1w3","Murmur of hypertrophic obstructive cardiomyopathy?","Systolic crescendo-decrescendo murmur at left sternal border, increased by decreased preload (Valsalva, standing).","Sopro sistólico que piora com Valsalva."],["fnn1ya19f","What causes outflow obstruction in HOCM?","Asymmetric septal hypertrophy and systolic anterior motion of the mitral valve.","Septo e mitral."],["phnq9z139","Treatment of hypertrophic cardiomyopathy?","Beta-blockers or nondihydropyridine calcium channel blockers, mavacamten; avoid dehydration and vasodilators; ICD if high risk; septal reduction if refractory.","Betabloqueador e verapamil."],["1husgisv2","Which drugs should be avoided in HOCM?","Drugs that reduce preload or afterload (nitrates, diuretics, vasodilators) and positive inotropes like digoxin.","Diuréticos e vasodilatadores."],["190j47l22","What is restrictive cardiomyopathy?","Stiff ventricles with impaired diastolic filling; normal or near-normal wall thickness and systolic function.","Ventrículo rígido."],["l2sw6y1jp","Causes of restrictive cardiomyopathy?","Amyloidosis (most common in adults), sarcoidosis, hemochromatosis, endocardial fibroelastosis, Löffler endocarditis, radiation, scleroderma.","Amiloidose, sarcoidose, hemocromatose."],["1uqc2te1p","ECG and echo findings in cardiac amyloidosis?","Low-voltage ECG despite thick myocardium on echo (granular, speckled).","Baixa voltagem e parede grossa."],["fofvw81v2","What is Löffler endocarditis?","Eosinophilic infiltration of the endomyocardium causing restrictive cardiomyopathy (hypereosinophilic syndrome).","Eosinófilos lesam o coração."],["1atcppop0","How do you distinguish restrictive cardiomyopathy from constrictive pericarditis?","Constrictive pericarditis has thickened/calcified pericardium and pericardial knock; restrictive has abnormal myocardium.","Biópsia, eco, BNP."],["1rwon4poz","What is Takotsubo cardiomyopathy?","Stress-induced apical ballooning of the LV with chest pain and ECG changes mimicking MI but no coronary obstruction; often in postmenopausal women after emotional stress.","Coração partido por estresse."],["zb9dqcyjz","What is arrhythmogenic right ventricular cardiomyopathy?","Fibrofatty replacement of RV myocardium causing ventricular arrhythmias and sudden death in young people; desmosome gene mutations.","VD substituído por gordura."],["1a9ytms1h","Common causes of myocarditis?","Viruses (Coxsackie B, adenovirus, parvovirus B19, HHV-6, COVID-19), Chagas, toxins, autoimmune, drugs, giant cell myocarditis.","Vírus."],["afu6gj83r","Clinical features of myocarditis?","Chest pain, dyspnea, arrhythmias, heart failure, elevated troponins, often after viral illness.","Dor, arritmia, insuficiência."],["6gffpctvd","What causes Chagas cardiomyopathy?","Trypanosoma cruzi infection: dilated cardiomyopathy with apical aneurysm, conduction abnormalities, megaesophagus/megacolon.","Trypanosoma cruzi."],["2fuevkr8q","What is infective endocarditis?","Infection of the endocardium/heart valves, usually bacterial.","Infecção da valva."],["nojosr1jq","Most common organism in acute endocarditis on normal valves?","Staphylococcus aureus (high virulence, large destructive vegetations).","S. aureus."],["1d7cqeyoc","Most common organism in endocarditis in IV drug users?","Staphylococcus aureus, often involving the tricuspid valve.","S. aureus na tricúspide."],["ikqm7g510","Which organisms cause subacute endocarditis on abnormal valves?","Viridans streptococci (low virulence, small vegetations), often after dental procedures.","Estreptococos viridans."],["a5mheidwt","Which organism causes endocarditis after prosthetic valve placement (early)?","Staphylococcus epidermidis.","S. epidermidis."],["1c5ypu521","Which organism causes endocarditis after GI/GU procedures?","Enterococcus.","Enterococo."],["1dqaf031t","Which organism's endocarditis is associated with colon cancer?","Streptococcus gallolyticus (formerly S. bovis).","S. gallolyticus."],["15yk3s7e5","What is the HACEK group?","Haemophilus, Aggregatibacter, Cardiobacterium, Eikenella, Kingella: culture-negative endocarditis organisms.","Bactérias exigentes."],["jt5za1q3h","Clinical signs of infective endocarditis?","Fever, new murmur, Roth spots, Osler nodes, Janeway lesions, splinter hemorrhages, anemia. Mnemonic: FROM JANE.","Febre, sopro, êmbolos."],["21z4sy1i2","What are Osler nodes?","Tender raised lesions on finger or toe pads (immune complex). Osler = Ouch.","Nódulos dolorosos."],["1xc9g881p","What are Janeway lesions?","Painless erythematous lesions on palms or soles (septic microemboli).","Manchas indolores."],["13am6rw1y","What are Roth spots?","Retinal hemorrhages with pale centers.","Hemorragia retiniana."],["1c9uf5c1v","Which valve is most commonly involved in infective endocarditis?","Mitral valve (tricuspid in IV drug use).","Mitral."],["1jw986q4f","How is infective endocarditis diagnosed?","Modified Duke criteria: positive blood cultures and echocardiographic evidence of vegetations, plus minor criteria.","Hemoculturas e eco."],["1obpadc17","What is nonbacterial thrombotic (marantic) endocarditis?","Sterile vegetations on valves associated with hypercoagulable states and advanced malignancy (e.g., pancreatic adenocarcinoma).","Vegetação estéril por câncer."],["1rjjiwo1c","What is Libman-Sacks endocarditis?","Sterile vegetations on both sides of the valve in systemic lupus erythematosus; most commonly mitral valve.","Vegetação estéril no lúpus."],["656djqnq5","What is acute rheumatic fever?","Consequence of pharyngeal infection with group A beta-hemolytic streptococci, due to molecular mimicry between M protein and self antigens.","Reação após faringite estreptocócica."],["rrj7vf1up","Which valve is most affected in rheumatic heart disease?","Mitral valve (mitral > aortic). Early: mitral regurgitation. Late: mitral stenosis.","Mitral."],["1natxnsn4","Major Jones criteria for acute rheumatic fever?","Joint (migratory polyarthritis), carditis (pancarditis), nodules (subcutaneous), erythema marginatum, Sydenham chorea. J♥NES.","JONES."],["wypd6us4o","What are Aschoff bodies?","Granulomas with giant cells in the myocardium in acute rheumatic carditis.","Granulomas cardíacos."],["c8cdd61dx","What are Anitschkow cells?","Enlarged macrophages with ovoid, wavy, rodlike nuclei (caterpillar cells) in rheumatic carditis.","Macrófagos lagarta."],["1s0iv20qe","Lab findings in acute rheumatic fever?","Elevated ASO or anti-DNase B titers; elevated ESR and CRP.","ASLO alto."],["16rhke8qj","Treatment and prevention of rheumatic fever?","Penicillin for acute infection and long-term penicillin prophylaxis to prevent recurrence; aspirin/NSAIDs for arthritis.","Penicilina."],["1th8gca14","What type of hypersensitivity is rheumatic fever?","Type II hypersensitivity (antibodies to M protein cross-react with self antigens).","Tipo II."],["8pfd0e19u","Most common cause of aortic stenosis in older adults?","Age-related calcific degeneration.","Calcificação senil."],["v7m5gz1qc","Most common cause of aortic stenosis in younger adults?","Bicuspid aortic valve.","Valva bicúspide."],["4bdwyp1hu","Causes of chronic aortic regurgitation?","Aortic root dilation (hypertension, Marfan, syphilis, ankylosing spondylitis), bicuspid valve, rheumatic disease.","Dilatação da raiz aórtica."],["1oyr3klp5","Causes of acute aortic regurgitation?","Infective endocarditis and aortic dissection.","Endocardite e dissecção."],["wrbfyd1p3","Most common cause of mitral regurgitation?","Mitral valve prolapse (myxomatous degeneration); also ischemic papillary muscle dysfunction, rheumatic disease, endocarditis, LV dilation.","Prolapso mitral."],["1w91minfp","Most common cause of mitral stenosis?","Rheumatic fever (fusion of commissures, fish-mouth valve).","Febre reumática."],["65dvvzhuo","Complications of mitral stenosis?","Left atrial dilation, atrial fibrillation, thrombus formation, pulmonary hypertension, dysphagia, hoarseness.","Fibrilação atrial e trombo."],["1juj7qp1o","What is acute pericarditis?","Inflammation of the pericardium: sharp pleuritic chest pain improved by sitting forward, friction rub, diffuse ST elevation and PR depression.","Inflamação do pericárdio."],["1r9w32yhj","Causes of acute pericarditis?","Idiopathic/viral (most common, e.g., Coxsackie B), uremia, MI, Dressler syndrome, autoimmune disease, radiation, malignancy, TB.","Vírus, uremia, IAM."],["z9jjg1s8r","Treatment of acute viral pericarditis?","NSAIDs plus colchicine.","AINE e colchicina."],["1neaog7np","What is uremic pericarditis treated with?","Dialysis.","Diálise."],["p6nhksdy5","What is cardiac tamponade?","Compression of the heart by pericardial fluid, decreasing ventricular filling and cardiac output.","Líquido comprime coração."],["s3jqpg1lw","Beck's triad of cardiac tamponade?","Hypotension, distended neck veins (JVD), muffled heart sounds.","Hipotensão, turgência, bulhas abafadas."],["511tyv16i","Other findings of cardiac tamponade?","Tachycardia, pulsus paradoxus, electrical alternans on ECG, equalization of diastolic pressures.","Pulso paradoxal."],["16zt9rs10","What is electrical alternans?","Beat-to-beat alternation of QRS amplitude due to the heart swinging in a large effusion.","QRS alternando altura."],["qdrcxuvp8","Treatment of cardiac tamponade?","Pericardiocentesis (or surgical drainage).","Pericardiocentese."],["1p4135w14","What is constrictive pericarditis?","Fibrotic, calcified pericardium restricting diastolic filling; causes include TB (developing countries), radiation, cardiac surgery, viral.","Pericárdio rígido."],["1ooa1xo7g","Findings in constrictive pericarditis?","Pericardial knock, Kussmaul sign, increased JVP with prominent y descent, pericardial calcification.","Knock pericárdico, Kussmaul."],["1u75xn015","What is syphilitic heart disease?","Tertiary syphilis disrupts vasa vasorum of the aorta causing aortic root dilation, aortic regurgitation, and thoracic aortic aneurysm (tree bark appearance).","Aortite."],["n8583hhnu","What is giant cell (temporal) arteritis?","Large vessel vasculitis of branches of the carotid artery in older adults (>50), often women.","Vasculite de grandes vasos."],["17ldb4v1l","Clinical features of giant cell arteritis?","Unilateral headache, jaw claudication, scalp tenderness, vision loss (ophthalmic artery), associated with polymyalgia rheumatica; high ESR.","Cefaleia, claudicação mandibular."],["10d73tf1d","Treatment of giant cell arteritis?","High-dose glucocorticoids immediately (before biopsy) to prevent blindness.","Corticoide imediato."],["1pfh0cjwn","Histology of giant cell arteritis?","Focal granulomatous inflammation of the media; skip lesions on biopsy.","Granulomas com células gigantes."],["fz0m0s1mm","What is Takayasu arteritis?","Granulomatous large vessel vasculitis of the aortic arch and branches, in Asian women <40; weak upper extremity pulses (pulseless disease), arm claudication, fever, night sweats.","Arterite sem pulso."],["1ghz5vz1j","What is polyarteritis nodosa?","Necrotizing vasculitis of medium arteries, sparing the lungs; associated with hepatitis B.","Vasculite de médio calibre."],["1w60s7ypm","Clinical features of polyarteritis nodosa?","Fever, weight loss, hypertension, abdominal pain, melena, neurologic dysfunction (mononeuritis multiplex), cutaneous eruptions, renal damage.","Hipertensão, dor, neuropatia."],["ztg0b91rj","Angiographic finding in polyarteritis nodosa?","Microaneurysms and spasm (string of pearls).","Microaneurismas."],["17fx8ui16","What is Kawasaki disease?","Medium vessel vasculitis in Asian children <4 years: fever ≥5 days, conjunctival injection, strawberry tongue, rash, hand-foot changes (desquamation), cervical lymphadenopathy. CRASH and burn.","Vasculite infantil."],["1huh74i16","Main complication of Kawasaki disease?","Coronary artery aneurysms (thrombosis, MI, rupture).","Aneurisma coronário."],["19nddlj10","Treatment of Kawasaki disease?","IV immunoglobulin and aspirin.","IVIG e aspirina."],["17o4v5z7z","What is Buerger disease (thromboangiitis obliterans)?","Segmental thrombosing vasculitis of small and medium vessels in heavy smokers; intermittent claudication, superficial thrombophlebitis, Raynaud, gangrene, autoamputation.","Vasculite em fumantes."],["sstpwrmz5","Treatment of Buerger disease?","Smoking cessation.","Parar de fumar."],["141ofzy11","What is granulomatosis with polyangiitis (Wegener)?","Necrotizing granulomatous small vessel vasculitis of upper respiratory tract, lungs, and kidneys; PR3-ANCA (c-ANCA).","Vasculite com granulomas."],["1orlrpj9b","Clinical features of granulomatosis with polyangiitis?","Sinusitis, saddle nose deformity, hemoptysis, otitis, rapidly progressive glomerulonephritis.","Seios, pulmão, rim."],["1gvmxspk1","What is microscopic polyangiitis?","Necrotizing small vessel vasculitis without granulomas; lung and kidney involvement, palpable purpura; MPO-ANCA (p-ANCA).","Vasculite sem granulomas."],["1knj13qik","What is eosinophilic granulomatosis with polyangiitis (Churg-Strauss)?","Asthma, sinusitis, eosinophilia, granulomatous vasculitis, mononeuritis multiplex; MPO-ANCA (p-ANCA).","Asma e eosinofilia."],["18xnz1410","What is IgA vasculitis (Henoch-Schönlein purpura)?","Most common childhood systemic vasculitis: palpable purpura on buttocks and legs, arthralgia, abdominal pain (intussusception risk), IgA nephropathy; often after URI.","Púrpura, artralgia, dor abdominal."],["1a7ppks1q","What is cryoglobulinemic vasculitis associated with?","Hepatitis C; palpable purpura, arthralgia, glomerulonephritis, low complement.","Hepatite C."],["x4xsth1u9","Which vasculitis is associated with c-ANCA (PR3)?","Granulomatosis with polyangiitis.","GPA."],["1c9i5so1a","Which vasculitides are associated with p-ANCA (MPO)?","Microscopic polyangiitis and eosinophilic granulomatosis with polyangiitis.","MPA e EGPA."],["4itv6u282","What is Behçet syndrome?","Variable vessel vasculitis with recurrent oral and genital ulcers, uveitis, skin lesions; associated with HLA-B51; Turkey and Silk Road populations.","Úlceras orais, genitais, uveíte."],["ofipmt15q","What is Raynaud phenomenon?","Decreased blood flow to the skin due to arteriolar vasospasm in response to cold or stress: white, blue, red color changes in fingers and toes.","Vasoespasmo dos dedos."],["19o10pp7y","Primary vs secondary Raynaud?","Primary (Raynaud disease): idiopathic, benign. Secondary: associated with SLE, scleroderma (CREST), other diseases.","Isolado vs doença associada."],["1g0pqs81v","Treatment of Raynaud phenomenon?","Avoid cold; dihydropyridine calcium channel blockers (nifedipine).","Bloqueador de cálcio."],["geg4g41eo","What is a strawberry (capillary) hemangioma?","Benign capillary hemangioma of infancy that grows rapidly then regresses spontaneously by 5-8 years.","Regride sozinho."],["rwrz1a1bn","What is a cherry hemangioma?","Benign capillary hemangioma in older adults that does not regress; increases with age.","Ponto vermelho no idoso."],["1pazmh7ez","What is a pyogenic granuloma?","Polypoid lobulated capillary hemangioma that bleeds and ulcerates; associated with trauma and pregnancy.","Lesão vascular que sangra."],["14cdv7f58","What is a cystic hygroma?","Cavernous lymphangioma of the neck; associated with Turner syndrome.","Linfangioma no pescoço."],["1o279f91s","What is a glomus tumor?","Benign painful red-blue tumor under the fingernails from modified smooth muscle cells of the thermoregulatory glomus body.","Tumor doloroso na unha."],["1gxzzvdtt","What is bacillary angiomatosis?","Benign capillary skin papules caused by Bartonella henselae in AIDS patients; mistaken for Kaposi sarcoma; neutrophilic infiltrate.","Bartonella."],["6qx2atdbe","What is Kaposi sarcoma?","Endothelial malignancy associated with HHV-8 and HIV; lesions of skin, mouth, GI tract, lungs; lymphocytic infiltrate.","HHV-8."],["1lbr0eczf","What is angiosarcoma?","Rare malignant vascular tumor of head, neck, breast; associated with radiation, chronic lymphedema (after mastectomy), and hepatic angiosarcoma with vinyl chloride, arsenic, Thorotrast.","Câncer vascular."],["1rixt9z1t","What is Sturge-Weber syndrome?","Congenital, sporadic GNAQ mutation: port-wine stain (V1 distribution), leptomeningeal angiomas, seizures, glaucoma, intellectual disability.","Mancha vinho do Porto e encefalotrigeminal."],["1lcb6szo6","What is shock and its main types?","Inadequate tissue perfusion; hypovolemic, cardiogenic, obstructive, distributive (septic, anaphylactic, neurogenic).","Perfusão inadequada."],["neimz968n","What is the most important early sign of shock?","Tachycardia and signs of hypoperfusion (altered mental status, decreased urine output, increased lactate).","Taquicardia."],["1ft3t62qb","What is syncope's most common cause?","Vasovagal (reflex) syncope.","Vasovagal."],["9rdks71re","What is the typical prodrome of vasovagal syncope?","Lightheadedness, warmth, nausea, diaphoresis, pallor after triggers like standing or emotional stress.","Calor, náusea, palidez."],["1rtt5k7fn","What is the danger of exertional syncope?","Suggests structural heart disease (aortic stenosis, HCM) or arrhythmia; requires evaluation.","Causa cardíaca."],["4asf9u1sb","What is the most common cause of mitral valve prolapse?","Myxomatous degeneration (primary or secondary to connective tissue disease).","Degeneração mixomatosa."],["1ocqzpp5v","Which connective tissue disorders cause mitral valve prolapse?","Marfan syndrome, Ehlers-Danlos syndrome, ADPKD.","Marfan e Ehlers-Danlos."],["hcdh4agu5","What is the main risk of a bicuspid aortic valve?","Early calcific aortic stenosis, aortic regurgitation, aortic dilation/dissection.","Estenose aórtica precoce."],["14zxo3e1o","What is carcinoid heart disease?","Right-sided valvular fibrosis (tricuspid regurgitation, pulmonic stenosis) from serotonin in carcinoid syndrome with liver metastases.","Lesão por serotonina."],["9yb53jxio","Why is carcinoid heart disease usually right-sided?","Serotonin is inactivated by monoamine oxidase in the lungs before reaching the left heart.","Pulmão inativa serotonina."],["1ovehb2w0","What is the role of pulmonary hypertension in right heart failure?","Increased afterload on the RV leads to RV hypertrophy and eventually failure (cor pulmonale).","Sobrecarga do VD."],["1qffiwt1p","What is the Wells criteria used for?","Estimating pretest probability of DVT or pulmonary embolism.","Probabilidade de TEP."],["6vbneye2c","What is Virchow's triad?","Stasis, hypercoagulability, endothelial damage (risk factors for venous thrombosis).","Estase, lesão, hipercoagulabilidade."],["1yg8sgy3q","What is the most common source of pulmonary emboli?","Deep veins of the lower extremities (above the knee).","Veias profundas da perna."],["xi6pf41ca","What is superficial thrombophlebitis associated with when migratory?","Trousseau syndrome (visceral malignancy, e.g., pancreatic cancer).","Câncer de pâncreas."],["1yqo6f71u","What is superior vena cava syndrome?","Obstruction of the SVC, often by malignancy (lung cancer, lymphoma) or thrombosis: facial plethora, arm and face edema, distended neck veins.","Obstrução da cava."],["8od0j4y8y","What is the mechanism of varicose veins?","Incompetent venous valves leading to dilated tortuous superficial veins; increased venous pressure.","Valvas venosas incompetentes."],["xfna8bm87","What is chronic venous insufficiency's typical skin finding?","Brownish stasis dermatitis and venous ulcers near the medial malleolus.","Hiperpigmentação e úlcera."],["13nvc5nfi","What is high-output heart failure and its causes?","Heart failure with increased cardiac output: severe anemia, thyrotoxicosis, AV fistulas, beriberi, Paget disease of bone, pregnancy.","Débito alto; anemia, tireoide, fístula."],["1oseugm1r","What is peripartum cardiomyopathy?","Dilated cardiomyopathy in the last month of pregnancy or within 5 months after delivery, with reduced EF.","IC no fim da gestação."],["124pl78tq","What cardiac finding is classic in hemochromatosis?","Dilated or restrictive cardiomyopathy from iron deposition.","Cardiomiopatia."],["1sg5i8o34","What is the most common cardiac manifestation of sarcoidosis?","Conduction abnormalities (heart block) and ventricular arrhythmias; can cause restrictive cardiomyopathy.","Bloqueio e arritmia."],["1fm8devth","What is the classic cardiac lesion in SLE?","Libman-Sacks endocarditis; also pericarditis (most common cardiac manifestation).","Libman-Sacks."],["pqvnuc1lc","What valve finding occurs with chronic use of ergot derivatives or fenfluramine?","Fibrotic valvulopathy similar to carcinoid heart disease (serotonin 5-HT2B receptor agonism).","Fibrose valvar."],["1ihb70zfa","Which cardiac effect is associated with hyperthyroidism?","Sinus tachycardia, atrial fibrillation, high-output heart failure.","Taquicardia e FA."],["1jpc76zha","Which cardiac effect is associated with hypothyroidism?","Bradycardia, pericardial effusion, diastolic dysfunction, hyperlipidemia.","Bradicardia e derrame."],["q2p88ff6w","What is the mechanism of septic shock hypotension?","Cytokines (TNF, IL-1) and NO cause widespread vasodilation and capillary leak; decreased SVR.","Vasodilatação."],["jauyn6yy4","What is the mechanism of anaphylactic shock?","IgE-mediated mast cell degranulation with histamine release causing vasodilation and capillary leak; treat with IM epinephrine.","IgE e histamina."]]},{"name":"Pharmacology","cards":[["iw5u6y8w3","First-line drug classes for primary hypertension?","Thiazide diuretics, ACE inhibitors, ARBs, dihydropyridine calcium channel blockers.","Tiazídico, IECA/BRA, BCC."],["yfj00zaw1","Preferred antihypertensives in hypertension with heart failure?","Diuretics, ACE inhibitors/ARBs/ARNIs, beta-blockers (compensated HF), aldosterone antagonists.","IECA, betabloqueador, diurético."],["ypbbl315r","Preferred antihypertensives in hypertension with diabetes or CKD with proteinuria?","ACE inhibitors or ARBs (protective against diabetic nephropathy).","IECA ou BRA."],["pymoo2mac","Preferred antihypertensives in pregnancy?","Labetalol, nifedipine, methyldopa, hydralazine. Mnemonic: Love My Nifedipine Hydralazine.","Labetalol, nifedipino, metildopa."],["1wvaogk1u","Which antihypertensives are contraindicated in pregnancy?","ACE inhibitors, ARBs, and direct renin inhibitors (fetal renal toxicity).","IECA, BRA, aliscireno."],["1xfpj9j10","Which antihypertensive is preferred in hypertension with BPH?","Alpha-1 blockers (prazosin, terazosin, doxazosin).","Alfabloqueador."],["ww18y31ip","Mechanism of dihydropyridine calcium channel blockers?","Block voltage-dependent L-type Ca2+ channels mainly in vascular smooth muscle, causing vasodilation (amlodipine, nifedipine).","Vasodilatam artérias."],["sgncw41a4","Mechanism of nondihydropyridine calcium channel blockers?","Block L-type Ca2+ channels mainly in the heart, decreasing HR, AV conduction, contractility (verapamil, diltiazem).","Agem no coração."],["1d2h7dvs9","Uses of dihydropyridine CCBs?","Hypertension, angina (including vasospastic), Raynaud phenomenon; nimodipine for subarachnoid hemorrhage; clevidipine for hypertensive emergency.","Hipertensão, angina, Raynaud."],["bu1g9886i","Uses of nondihydropyridine CCBs?","Hypertension, angina, atrial fibrillation/flutter rate control.","Arritmia e angina."],["1y4h1391n","Adverse effects of dihydropyridine CCBs?","Peripheral edema, flushing, dizziness, gingival hyperplasia, reflex tachycardia.","Edema e rubor."],["wh5tmk18k","Adverse effects of verapamil?","Constipation, AV block, bradycardia, heart failure exacerbation, gingival hyperplasia.","Constipação e bradicardia."],["1uz7vsr1c","Mechanism of hydralazine?","Increases cGMP causing smooth muscle relaxation; arterioles more than veins (decreases afterload).","Vasodilata arteríolas."],["1bj3z5c8u","Uses of hydralazine?","Severe hypertension (especially acute), heart failure with nitrate, hypertension in pregnancy.","Hipertensão grave e gestação."],["82ud1y1lx","Adverse effects of hydralazine?","Reflex tachycardia (give with beta-blocker), fluid retention, headache, angina, drug-induced lupus.","Taquicardia reflexa, lúpus."],["1naoq121a","Why is hydralazine dangerous in angina or coronary disease without a beta-blocker?","Reflex tachycardia increases myocardial O2 demand.","Taquicardia aumenta isquemia."],["pfj2agvxh","Drugs used for hypertensive emergency?","Clevidipine, esmolol, fenoldopam, labetalol, nicardipine, nitroprusside.","Nitroprussiato, labetalol, nicardipino."],["104g5gf1o","Mechanism and toxicity of nitroprusside?","Short-acting; increases cGMP via direct NO release; can cause cyanide toxicity (treat with sodium thiosulfate, hydroxocobalamin).","Libera NO; cianeto."],["1bmkrpt1t","Mechanism of fenoldopam?","Dopamine D1 receptor agonist: coronary, peripheral, renal, and splanchnic vasodilation; increases natriuresis.","Agonista D1."],["exss492wk","Mechanism of nitrates (nitroglycerin, isosorbide)?","Release NO in smooth muscle, increasing cGMP and relaxation; dilate veins more than arteries (decreasing preload).","Libera NO; veias."],["8cvjk114f","Uses of nitrates?","Angina, acute coronary syndrome, pulmonary edema.","Angina e edema pulmonar."],["e4lr5313x","Adverse effects of nitrates?","Reflex tachycardia, methemoglobinemia, hypotension, flushing, headache; tolerance (need nitrate-free interval).","Cefaleia e hipotensão."],["1uhvuba1j","What is 'Monday disease'?","Industrial nitrate exposure: tolerance develops during the week, lost over the weekend, causing headache, tachycardia, dizziness on Monday.","Tolerância perdida no fim de semana."],["lqk89x3f7","Goal of antianginal therapy?","Reduce myocardial O2 consumption by decreasing EDV, BP, HR, contractility.","Reduzir consumo de O2."],["gcq11y1d0","Effect of nitrates vs beta-blockers on EDV and HR?","Nitrates: decrease EDV, reflex increase in HR. Beta-blockers: increase EDV, decrease HR. Combined: both effects balanced.","Nitrato baixa; betabloqueador sobe."],["zglf761p2","Which beta-blockers are contraindicated in angina?","Partial agonists (pindolol, acebutolol) because of intrinsic sympathomimetic activity.","Agonistas parciais."],["9es76v1n3","Mechanism and use of ranolazine?","Inhibits the late phase of Na+ current, reducing diastolic wall tension and O2 consumption; refractory angina.","Inibe corrente de sódio tardia."],["1s7fs8yda","Adverse effects of ranolazine?","Constipation, dizziness, headache, nausea, QT prolongation.","QT longo."],["15fuxz011","Mechanism of HMG-CoA reductase inhibitors (statins)?","Inhibit conversion of HMG-CoA to mevalonate, decreasing cholesterol synthesis and increasing LDL receptors.","Inibem HMG-CoA redutase."],["1fwt1zd1f","Lipid effects of statins?","Large decrease in LDL, moderate increase in HDL, moderate decrease in triglycerides; decreased mortality in CAD.","LDL cai muito."],["fnvgj73a5","Adverse effects of statins?","Hepatotoxicity (increased LFTs), myopathy (especially with fibrates or niacin), rhabdomyolysis.","Miopatia e hepatotoxicidade."],["15b7ete18","Lipid effects and mechanism of bile acid resins?","Cholestyramine, colestipol, colesevelam: decrease LDL; slight increase in triglycerides; bind bile acids in gut.","LDL cai; ligam bile."],["1ytbbo81e","Adverse effects of bile acid resins?","GI upset, decreased absorption of fat-soluble vitamins and other drugs, cholesterol gallstones, increased triglycerides.","GI e TG sobe."],["xw76g1ufm","Adverse effects of ezetimibe?","Rare increased LFTs, diarrhea.","Diarreia."],["1pprg9vhm","Mechanism and lipid effects of fibrates?","Activate PPAR-alpha to upregulate LPL; greatest decrease in triglycerides, increase in HDL (gemfibrozil, fenofibrate).","PPAR-alfa; TG cai."],["11hqwu11h","Adverse effects of fibrates?","Myopathy (especially with statins), cholesterol gallstones (inhibit 7-alpha-hydroxylase).","Miopatia e cálculos."],["19qv2i51l","Mechanism of PCSK9 inhibitors?","Monoclonal antibodies (alirocumab, evolocumab) inactivate PCSK9, increasing LDL receptor recycling and lowering LDL.","Mais receptor de LDL."],["1s8l562e5","Mechanism and use of lomitapide?","Inhibits microsomal triglyceride transfer protein, decreasing VLDL and LDL; used for homozygous familial hypercholesterolemia.","Inibe MTP; HF homozigótica."],["q9s3ai1df","Mechanism of icosapent ethyl and omega-3 fatty acids?","Decrease triglycerides by reducing hepatic VLDL production; icosapent ethyl reduces cardiovascular events.","Reduzem TG."],["1bkelqqvh","Mechanism of digoxin?","Inhibits Na+/K+-ATPase, increasing intracellular Na+ and Ca2+ (via Na+/Ca2+ exchanger), increasing contractility; stimulates vagus nerve (decreases HR).","Inibe Na/K-ATPase."],["gqycex1es","Uses of digoxin?","Heart failure (symptom relief, decreases hospitalizations) and atrial fibrillation rate control.","IC e FA."],["epj30k57q","Signs of digoxin toxicity?","Cholinergic effects (nausea, vomiting, diarrhea), blurry yellow vision, arrhythmias, AV block, hyperkalemia (poor prognosis).","Visão amarela, náusea, arritmia."],["hr6kotnir","Factors predisposing to digoxin toxicity?","Renal failure (decreased excretion), hypokalemia (digoxin binds the K+ site more), drugs that displace digoxin (verapamil, amiodarone, quinidine).","Hipocalemia, insuficiência renal."],["1xrl2qo1w","Treatment of digoxin toxicity?","Correct K+, Mg2+; cardiac pacer; anti-digoxin Fab fragments; avoid giving calcium if possible.","Anticorpo Fab."],["wke8477gb","Mechanism of sacubitril?","Neprilysin inhibitor that increases natriuretic peptides (ANP, BNP); combined with valsartan (ARNI) for HFrEF.","Inibe neprilisina."],["xiz0esuh3","Why is sacubitril combined with an ARB rather than an ACE inhibitor?","Combination with ACE inhibitor greatly increases angioedema risk (both raise bradykinin).","Angioedema."],["1s60fd1f3","Mechanism and use of ivabradine?","Selectively inhibits funny current (If) in SA node, lowering HR; HFrEF patients in sinus rhythm with elevated HR despite beta-blockers.","Inibe corrente If."],["ua8sukp0v","Adverse effects of ivabradine?","Luminous phenomena (visual brightness), hypertension, bradycardia.","Fosfenos."],["1uinmp8cn","Mechanism of SGLT2 inhibitors in heart failure?","Promote natriuresis and glucosuria, reduce preload; reduce HF hospitalizations and mortality (dapagliflozin, empagliflozin).","Diurese e menos carga."],["1luimff1a","What are Class I antiarrhythmics?","Na+ channel blockers that decrease slope of phase 0 depolarization; state-dependent (more effective in rapidly firing tissue).","Bloqueiam canal de sódio."],["8crce3i1c","Class IA antiarrhythmics and their effects?","Quinidine, procainamide, disopyramide; increase AP duration and ERP, increase QT; moderate Na+ blockade. 'The Queen Proclaims Diso's pyramid.'","Prolongam potencial de ação."],["hrzck1vzl","Adverse effects of class IA drugs?","Cinchonism (quinidine: headache, tinnitus), drug-induced lupus (procainamide), heart failure (disopyramide), thrombocytopenia, torsades.","Cinchonismo, lúpus."],["ue5d201h8","Class IB antiarrhythmics and their effects?","Lidocaine, mexiletine; decrease AP duration; preferentially affect ischemic or depolarized Purkinje and ventricular tissue.","Encurtam potencial de ação."],["fjew821ws","Use of class IB drugs?","Acute ventricular arrhythmias (especially post-MI) and digitalis-induced arrhythmias. 'I'd Buy Liddy's Mexican tacos.'","Arritmia ventricular pós-IAM."],["goq3sbwsq","Adverse effects of lidocaine?","CNS stimulation/depression (seizures), cardiovascular depression.","Neurotoxicidade."],["q8i8mx1cg","Class IC antiarrhythmics and their effects?","Flecainide, propafenone; significantly prolong ERP in AV node and accessory pathways; no effect on AP duration in ventricles.","Sem efeito na duração."],["4q1g7kbfg","Contraindications to class IC drugs?","Structural heart disease and post-MI (proarrhythmic, increased mortality, CAST trial).","Doença estrutural."],["1qh8pojde","Use of class IC drugs?","SVTs including atrial fibrillation in patients without structural heart disease; 'pill in the pocket'.","FA sem cardiopatia."],["i92u8y5ot","What are Class II antiarrhythmics?","Beta-blockers: decrease SA and AV nodal activity by reducing cAMP and Ca2+ currents; slow phase 4 slope; prolong PR interval.","Betabloqueadores."],["7vx54kqv7","Use of class II antiarrhythmics?","SVT, rate control of atrial fibrillation and flutter, ventricular rate control.","Taquicardias e pós-IAM."],["nm7m0x8wo","Which beta-blocker is very short-acting for acute SVT?","Esmolol.","Esmolol."],["1mkkxg718","Adverse effects of beta-blockers?","Impotence, exacerbation of COPD/asthma, bradycardia, AV block, heart failure, sedation, masked hypoglycemia, dyslipidemia (metoprolol).","Bradicardia e broncoespasmo."],["15rnvd118","Treatment of beta-blocker overdose?","Saline, atropine, glucagon (increases cAMP independent of beta receptors).","Glucagon."],["1v0v83p17","Why should nonselective beta-blockers be avoided in cocaine-induced chest pain (traditional teaching)?","Risk of unopposed alpha-adrenergic vasoconstriction.","Alfa sem oposição."],["fpqazy7gf","What are Class III antiarrhythmics?","K+ channel blockers (amiodarone, ibutilide, dofetilide, sotalol): increase AP duration and ERP, prolong QT.","Bloqueiam potássio."],["1cjfuhv1n","Adverse effects of sotalol?","Torsades de pointes, excessive beta-blockade.","Torsades."],["1gxcl6zvg","Adverse effect of ibutilide and dofetilide?","Torsades de pointes.","Torsades."],["o1iyqkr12","Adverse effects of amiodarone?","Pulmonary fibrosis, hepatotoxicity, hypo- or hyperthyroidism, corneal deposits, blue-gray skin, photodermatitis, neurologic effects, constipation, bradycardia, heart block, heart failure.","Pulmão, tireoide, fígado."],["bu7n3b13b","Why does amiodarone affect the thyroid?","It is 40% iodine by weight and resembles thyroid hormone.","Contém iodo."],["1jjkd6c13","What monitoring is required with amiodarone?","Thyroid function tests, liver function tests, pulmonary function tests (and chest x-ray), eye exams.","Pulmão, tireoide, fígado."],["1swyr7u1l","Which classes of antiarrhythmics does amiodarone have properties of?","All four (I, II, III, IV), though classified as class III.","Todas."],["h1vmdgi78","Why does amiodarone rarely cause torsades despite QT prolongation?","Its multichannel effects make it less proarrhythmic.","Bloqueio uniforme."],["1eas6hpn7","What are Class IV antiarrhythmics?","Nondihydropyridine calcium channel blockers (verapamil, diltiazem): decrease conduction velocity, increase ERP and PR interval.","Bloqueadores de cálcio."],["9cdl8rdx0","Use of class IV antiarrhythmics?","Prevention of nodal arrhythmias (SVT), rate control in atrial fibrillation.","Taquicardia supraventricular."],["17vim401b","Mechanism and use of adenosine?","Increases K+ efflux out of cells, hyperpolarizing and decreasing Ca2+ current; first-line for diagnosing/terminating reentrant SVT; very short-acting.","Bloqueia nó AV."],["ro8g51plh","Adverse effects of adenosine?","Flushing, hypotension, chest pain, sense of impending doom, bronchospasm.","Rubor e sensação de morte."],["1tzxe9y9y","Which drugs blunt the effect of adenosine?","Theophylline and caffeine (adenosine receptor antagonists).","Cafeína e teofilina."],["cmjzye630","Mechanism and use of magnesium as an antiarrhythmic?","Effective in torsades de pointes and digoxin toxicity.","Torsades e intoxicação digitálica."],["1901nr91g","Mechanism of atropine in bradycardia?","Muscarinic antagonist that increases SA node firing and AV conduction.","Bloqueia vago."],["1kqa6qh1v","Which anticoagulant is preferred for nonvalvular atrial fibrillation?","Direct oral anticoagulants (apixaban, rivaroxaban, dabigatran, edoxaban) over warfarin.","DOACs."],["1pfh1bjyl","Which anticoagulant is required for mechanical heart valves?","Warfarin (DOACs are contraindicated).","Varfarina."],["ouqmz42x9","What score is used to estimate stroke risk in atrial fibrillation?","CHA2DS2-VASc score.","CHA2DS2-VASc."],["95oxq01ga","Mechanism of ACE inhibitors?","Inhibit angiotensin-converting enzyme, reducing angiotensin II and aldosterone; increase bradykinin.","Inibem ECA."],["1fzbe8j1v","Uses of ACE inhibitors?","Hypertension, HFrEF (decrease mortality), proteinuria/diabetic nephropathy, post-MI (prevent remodeling).","Hipertensão, IC, proteinúria."],["1d8chyt1k","Adverse effects of ACE inhibitors?","Cough, angioedema (bradykinin), teratogenicity, increased creatinine (decreased GFR), hyperkalemia, hypotension. Mnemonic: CATCHH.","Tosse, angioedema, hipercalemia."],["1ve4d8we1","When are ACE inhibitors contraindicated?","History of angioedema (C1 esterase inhibitor deficiency), pregnancy, bilateral renal artery stenosis.","Gestação e angioedema."],["1ntx31mdl","Mechanism of ARBs?","Block angiotensin II at the AT1 receptor; no increase in bradykinin (less cough and angioedema).","Bloqueiam AT1."],["emugck1df","Mechanism of aliskiren?","Direct renin inhibitor that blocks conversion of angiotensinogen to angiotensin I.","Inibe renina."],["533lfd5i5","Mechanism of clonidine and guanfacine?","Central alpha-2 agonists decreasing sympathetic outflow.","Agonistas alfa-2."],["1mq8s601f","Adverse effect of abrupt clonidine withdrawal?","Rebound hypertension.","Hipertensão rebote."],["2g90yb1wu","Mechanism of methyldopa?","Central alpha-2 agonist (as alpha-methylnorepinephrine), decreasing sympathetic outflow.","Agonista alfa-2."],["1ccqm8d4e","Adverse effect of methyldopa?","Direct Coombs-positive hemolytic anemia, drug-induced lupus, hyperprolactinemia, sedation.","Hemólise Coombs positiva."],["1b1zpct8h","Mechanism of minoxidil?","K+ channel opener that hyperpolarizes and relaxes vascular smooth muscle; used for severe hypertension and alopecia.","Abre canal de K."],["xwzkc03hq","Adverse effects of minoxidil?","Hypertrichosis, pericardial effusion, reflex tachycardia, fluid retention.","Hirsutismo e edema."],["igf2gj1f0","Which drugs reduce mortality in pulmonary arterial hypertension?","Endothelin receptor antagonists (bosentan, ambrisentan), PDE5 inhibitors (sildenafil), prostacyclin analogs (epoprostenol, iloprost), guanylate cyclase stimulator (riociguat).","Prostanoides e outros."],["1ghhem0jt","Adverse effect of bosentan?","Hepatotoxicity (monitor LFTs) and teratogenicity.","Hepatotoxicidade."],["1vznhr1hp","Adverse effects of epoprostenol?","Flushing, jaw pain.","Rubor e cefaleia."],["5irfis1h4","Which drug class is used for initial treatment of acute pulmonary edema in heart failure?","Loop diuretics (furosemide), plus nitrates and positive pressure ventilation as needed.","Diuréticos de alça."],["elreg61c6","Mechanism and use of dobutamine?","Beta1 agonist (> beta2, alpha) increasing contractility and CO; acute decompensated heart failure and cardiogenic shock; pharmacologic stress testing.","Agonista beta-1."],["1db4fmhxe","Mechanism and use of milrinone?","PDE3 inhibitor increasing cAMP: inotropy in heart and vasodilation in vessels; short-term in acute decompensated heart failure.","Inibe PDE3."],["15aqgir1y","What is the vasopressor of choice in septic shock?","Norepinephrine.","Noradrenalina."],["11sslqkgk","What does low-dose vs high-dose dopamine do?","Low: D1 (renal vasodilation). Medium: beta1 (inotropy). High: alpha1 (vasoconstriction).","Rim vs vasoconstrição."],["1res5d7c8","Mechanism and use of phenylephrine?","Alpha1 agonist; hypotension (vasoconstriction), decongestant; causes reflex bradycardia.","Agonista alfa-1."],["864mggwsi","Mechanism and use of vasopressin in shock?","V1 receptor vasoconstriction; adjunct in septic shock refractory to norepinephrine.","Agonista V1."],["bechhk1ow","Mechanism of aspirin in coronary disease?","Irreversibly inhibits COX-1 in platelets, decreasing thromboxane A2 and platelet aggregation.","Inibe tromboxano."],["tdhp7l11z","Mechanism of clopidogrel, prasugrel, ticagrelor?","Block ADP P2Y12 receptors, preventing GPIIb/IIIa expression; clopidogrel and prasugrel irreversible, ticagrelor reversible.","Bloqueiam P2Y12."],["1hmalsn1k","Why may clopidogrel be less effective in some patients?","Prodrug requires CYP2C19 activation; poor metabolizers have reduced effect.","CYP2C19 lento."],["c094xj1iw","Mechanism and use of glycoprotein IIb/IIIa inhibitors?","Abciximab, eptifibatide, tirofiban block GPIIb/IIIa binding of fibrinogen; used in high-risk PCI.","Bloqueiam agregação."],["16d8046tw","Mechanism and use of cilostazol?","PDE3 inhibitor increasing cAMP in platelets and vessels; intermittent claudication; contraindicated in heart failure.","Inibe PDE3; claudicação."],["1gd7h2c1c","Mechanism of unfractionated heparin?","Activates antithrombin, inactivating thrombin (IIa) and factor Xa; monitored by PTT.","Ativa antitrombina."],["1fgswnx65","Mechanism of low-molecular-weight heparin?","Activates antithrombin, acting mainly on factor Xa; more predictable, less HIT; renally cleared (enoxaparin).","Inibe fator Xa."],["18yi34t1s","What is heparin-induced thrombocytopenia (HIT)?","IgG antibodies against heparin-bound platelet factor 4 activate platelets, causing thrombocytopenia and thrombosis.","Anticorpo anti-PF4."],["1p2nojmy9","Treatment of HIT?","Stop heparin; use non-heparin anticoagulant (argatroban, bivalirudin, fondaparinux).","Argatroban ou DOAC."],["uxohspg2v","Reversal agent for heparin?","Protamine sulfate.","Protamina."],["uvonyjyjc","Mechanism of warfarin?","Inhibits vitamin K epoxide reductase, interfering with gamma-carboxylation of factors II, VII, IX, X and proteins C and S; monitored by PT/INR.","Inibe vitamina K."],["1ne8icbpj","Why is warfarin initially paired with heparin?","Warfarin initially decreases protein C (short half-life), creating a transient hypercoagulable state (risk of warfarin skin necrosis).","Estado pró-trombótico inicial."],["u1xvwt783","Reversal of warfarin?","Vitamin K; for rapid reversal, prothrombin complex concentrate (or fresh frozen plasma).","Vitamina K e PCC."],["r5hpmy1sr","Mechanism and reversal of dabigatran?","Direct thrombin inhibitor; reversed by idarucizumab.","Inibe trombina; idarucizumabe."],["y64ozt1h7","Mechanism and reversal of apixaban and rivaroxaban?","Direct factor Xa inhibitors; reversed by andexanet alfa.","Inibem Xa; andexanet."],["a0yrry1ou","Mechanism of fibrinolytics (alteplase, tenecteplase)?","Convert plasminogen to plasmin, cleaving thrombin and fibrin clots.","Plasmina."],["1ryzqu2ka","Contraindications to thrombolytics?","Active bleeding, history of intracranial hemorrhage, recent surgery, known bleeding disorder, severe hypertension.","Sangramento ativo, AVC."],["a2nnyat00","Reversal of thrombolytic-induced bleeding?","Aminocaproic acid or tranexamic acid (antifibrinolytics); cryoprecipitate, platelets, FFP.","Ácido aminocaproico."],["mtt11g1rj","What drug class should be avoided in HFrEF because it can worsen outcomes?","Nondihydropyridine calcium channel blockers (verapamil, diltiazem); also NSAIDs and thiazolidinediones.","BCC não di-hidropiridínico."],["1ew8gkoud","Which antiarrhythmic is preferred for atrial fibrillation in patients with HFrEF?","Amiodarone (or dofetilide).","Amiodarona."],["1f68eoa1j","What is the mechanism of mavacamten?","Cardiac myosin inhibitor that reduces hypercontractility in obstructive hypertrophic cardiomyopathy.","Inibe miosina."],["on3w6wscd","Which electrolyte abnormality does spironolactone cause and in which combination is it dangerous?","Hyperkalemia; dangerous with ACE inhibitors/ARBs, potassium supplements, or renal failure.","Hipercalemia com IECA."],["m2suw6eno","Which beta-blockers are approved to reduce mortality in HFrEF?","Carvedilol, metoprolol succinate, bisoprolol.","Carvedilol, metoprolol, bisoprolol."],["16dy9yl1q","Which beta-blocker has both alpha and beta blocking effects?","Carvedilol and labetalol.","Carvedilol e labetalol."],["9go3261t2","Which beta-blocker is used for hypertensive emergency and in pregnancy?","Labetalol.","Labetalol."],["1lvfr511t","Which drug combination is preferred for HFrEF in self-identified Black patients?","Hydralazine plus isosorbide dinitrate (added to standard therapy).","Hidralazina e nitrato."],["1l952rej8","Which antiarrhythmic drug causes drug-induced lupus?","Procainamide (also hydralazine among cardiac drugs).","Procainamida."],["1ht2meraw","Which antianginal drug class should be avoided with ivabradine because of bradycardia?","Nondihydropyridine calcium channel blockers (verapamil, diltiazem).","Betabloqueador."]]},{"name":"Physiology (Part 1)","cards":[["1d5cj2epe","What is the formula for cardiac output?","CO = stroke volume x heart rate.","Volume sistólico x FC."],["115tswp1l","What is the Fick principle for cardiac output?","CO = rate of O2 consumption / (arterial O2 content - venous O2 content).","Consumo de O2 / diferença arteriovenosa."],["1itk38w1n","What is the formula for mean arterial pressure?","MAP = CO x total peripheral resistance; or approximately diastolic pressure + 1/3 pulse pressure.","2/3 diastólica + 1/3 sistólica."],["1f2rbqq1l","What is pulse pressure and what determines it?","Systolic - diastolic pressure; proportional to stroke volume and inversely proportional to arterial compliance.","Sistólica menos diastólica."],["1so7ttn5g","What conditions widen pulse pressure?","Aortic regurgitation, aortic stiffening (isolated systolic hypertension in elderly), hyperthyroidism, obstructive sleep apnea, exercise, heart block.","Regurgitação aórtica, hipertireoidismo."],["gja63hieg","What conditions narrow pulse pressure?","Aortic stenosis, cardiogenic shock, cardiac tamponade, advanced heart failure.","Estenose aórtica, choque, tamponamento."],["1vdncompz","What is stroke volume?","End-diastolic volume minus end-systolic volume.","Volume ejetado."],["5jf3akcu2","What is ejection fraction and normal value?","EF = SV / EDV; normal about 55-70%.","VS/VDF; 55-70%."],["s5gqdibac","Which three factors determine stroke volume?","Preload, afterload, and contractility.","Pré-carga, pós-carga, contratilidade."],["14wm68e1r","How does exercise initially increase cardiac output?","Increase in stroke volume (early) and heart rate (later, main contributor during intense exercise).","Aumenta FC e VS."],["ct7eql7wf","Why does very high heart rate decrease cardiac output?","Diastole shortens, decreasing ventricular filling time and stroke volume.","Pouco tempo de enchimento."],["lmw8nf3p5","What is preload?","Ventricular end-diastolic volume (wall stress at end of diastole); depends on venous return.","Volume diastólico final."],["1dqsemex2","What increases preload?","Increased venous tone, increased blood volume, venoconstriction, exercise, slower heart rate.","Volume, exercício, venoconstrição."],["1livufnj0","Which drugs decrease preload?","Venodilators like nitroglycerin; diuretics.","Venodilatadores e diuréticos."],["1c8rrgodm","What is afterload?","Pressure the ventricle must overcome to eject blood; approximated by MAP (or aortic pressure).","Pressão contra ejeção."],["18g0bvh1u","How does Laplace's law relate to afterload?","Wall tension = (pressure x radius) / (2 x wall thickness); ventricular hypertrophy reduces wall stress.","Parede mais grossa reduz tensão."],["1kjyis21e","Which drugs reduce afterload?","Arterial vasodilators (e.g., hydralazine), ACE inhibitors and ARBs (decrease both preload and afterload).","Vasodilatadores arteriais."],["1b9h1eb12","Why does left ventricle hypertrophy occur in chronic hypertension?","Increased afterload leads to concentric hypertrophy to normalize wall stress.","Compensar pós-carga."],["yw0u7zw3z","What increases myocardial contractility?","Catecholamines (beta1), increased intracellular Ca2+, decreased extracellular Na+, digoxin (Na+/K+-ATPase inhibition).","Catecolaminas, cálcio, digoxina."],["1qt60yhlc","What decreases myocardial contractility?","Beta-blockers, heart failure with systolic dysfunction, acidosis, hypoxia/hypercapnia, nondihydropyridine calcium channel blockers.","Betabloqueador, acidose, hipóxia."],["8pgs1o1es","What does the Frank-Starling law state?","Force of contraction is proportional to end-diastolic length of cardiac muscle fibers (preload).","Mais pré-carga, mais força."],["bvxb6debs","How do positive inotropes affect the Frank-Starling curve?","Shift the curve up (greater stroke volume at the same preload).","Curva sobe."],["heankj1ko","Which factors increase myocardial oxygen demand?","Increased contractility, afterload, heart rate, and ventricular diameter (wall tension).","Pós-carga, contratilidade, FC."],["15n8lg713","What is the formula for resistance in series vs parallel?","Series: R total = R1 + R2 + ... Parallel: 1/R total = 1/R1 + 1/R2 + ...","Soma vs soma dos inversos."],["1l9o026vm","What does Poiseuille's law state about vascular resistance?","R = 8 x viscosity x length / (pi x r^4). Resistance is inversely proportional to radius to the 4th power.","Raio à quarta potência."],["1d8uge579","What happens to resistance if a vessel radius is halved?","Resistance increases 16-fold.","Aumenta 16 vezes."],["1xaenrnvf","What determines blood viscosity?","Mainly hematocrit; increased in polycythemia, hyperproteinemia (multiple myeloma), hereditary spherocytosis.","Hematócrito."],["1ly35erdp","What is the relation of pressure, flow, and resistance?","Pressure gradient = flow x resistance (analogous to Ohm's law).","Pressão = fluxo x resistência."],["xy31eg148","What is the Reynolds number used for?","Predicts turbulence; turbulent flow causes bruits and murmurs.","Prever turbulência."],["1vjepah16","What happens during isovolumetric contraction?","Period between mitral valve closing and aortic valve opening; ventricular pressure rises with no volume change; highest O2 consumption.","Valvas fechadas, pressão sobe."],["l9h5wz1an","What happens during systolic ejection?","Period between aortic valve opening and closing.","Aorta aberta."],["rltkjwplt","What happens during isovolumetric relaxation?","Period between aortic valve closing and mitral valve opening; pressure falls with no volume change.","Valvas fechadas, pressão cai."],["12axfqb1h","What happens during rapid filling and reduced filling?","Rapid filling just after mitral valve opening; reduced filling just before mitral valve closure (atrial contraction).","Enchimento ventricular."],["y36kmj17g","What causes the first heart sound (S1)?","Mitral and tricuspid valve closure; loudest at mitral area.","Fechamento mitral e tricúspide."],["1all0qq14","What causes the second heart sound (S2)?","Aortic and pulmonary valve closure; loudest at left upper sternal border.","Fechamento aórtico e pulmonar."],["i4eab435f","What causes the third heart sound (S3)?","Rapid ventricular filling in early diastole; normal in children and pregnancy, abnormal in adults over 40 (dilated ventricle, increased filling pressures, heart failure, MR).","Enchimento rápido; sobrecarga."],["1txse92pa","What causes the fourth heart sound (S4)?","Atrial kick against a stiff ventricle in late diastole (atrial gallop); best heard at apex with patient in left lateral decubitus. Always abnormal.","Átrio contra ventrículo rígido."],["mopxwkcg5","Which conditions are associated with S4?","Ventricular hypertrophy (hypertension, aortic stenosis, hypertrophic cardiomyopathy), acute MI.","Hipertrofia e rigidez."],["1y5w20x1q","Why is S4 absent in atrial fibrillation?","No coordinated atrial contraction (no atrial kick).","Sem contração atrial."],["1854e28dh","What is the 'a wave' in the jugular venous pulse?","Atrial contraction; absent in atrial fibrillation.","Contração atrial."],["1l37vbq8n","What causes cannon a waves?","Atrium contracts against a closed tricuspid valve (AV dissociation, complete heart block, ventricular tachycardia).","Átrio contra valva fechada."],["zc45bm141","What is the 'c wave' in the jugular venous pulse?","RV contraction bulging the closed tricuspid valve into the atrium.","Tricúspide abaulando."],["2niw2t1ru","What is the 'x descent'?","Atrial relaxation and downward displacement of the closed tricuspid valve during ventricular contraction; absent in tricuspid regurgitation.","Relaxamento atrial."],["1q13jnrt9","What is the 'v wave' in the jugular venous pulse?","Increased right atrial pressure due to filling against a closed tricuspid valve.","Enchimento atrial."],["1jivdt01b","What is the 'y descent'?","Right atrial emptying into the RV after tricuspid valve opening; prominent in constrictive pericarditis, absent in cardiac tamponade.","Esvaziamento atrial."],["4omulzed5","What is normal splitting of S2?","Inspiration increases venous return to the right heart, delaying pulmonic valve closure (P2 after A2).","Desdobra na inspiração."],["1kiipf1an","What causes wide splitting of S2?","Delayed RV emptying: pulmonic stenosis, right bundle branch block; exaggerated normal splitting.","Atraso pulmonar."],["1j0qqwq1u","What causes fixed splitting of S2?","Atrial septal defect: left-to-right shunt increases RV volume regardless of breathing.","CIA."],["1lf6dp61g","What causes paradoxical splitting of S2?","Delayed aortic valve closure: aortic stenosis, left bundle branch block; P2 occurs before A2, and the split narrows on inspiration.","Atraso aórtico."],["11bfp0d1h","Which maneuver increases venous return (preload)?","Leg raise, squatting (also increases afterload), and inspiration (right heart).","Agachar ou elevar pernas."],["xv1qw41up","Which maneuvers decrease preload?","Valsalva (phase II), standing up suddenly, nitroglycerin.","Valsalva, ficar em pé."],["1jk1upt13","Which maneuvers increase afterload?","Hand grip (also squatting).","Preensão manual."],["1kkam4n1k","Which maneuver decreases afterload?","Amyl nitrite inhalation.","Nitrito de amila."],["1r9mtua3d","How do most murmurs change with increased preload?","Most murmurs increase (louder), except hypertrophic cardiomyopathy and mitral valve prolapse (which become softer/later).","Aumentam."],["15og5jsp2","How does hand grip affect murmurs?","Increases afterload: louder MR, AR, VSD; softer AS and HCM; MVP click occurs later.","Aumenta regurgitações."],["3asz8j1ua","How does Valsalva affect HCM and MVP murmurs?","Decreased preload makes the HCM murmur louder and the MVP click earlier.","Aumentam."],["bcal4h88v","Which side of the heart murmurs increase with inspiration?","Right-sided murmurs (Carvallo sign).","Lado direito."],["1vq7ffitn","Describe the murmur of aortic stenosis.","Crescendo-decrescendo systolic ejection murmur after an ejection click, radiating to carotids; best at right upper sternal border.","Ejeção em crescendo-decrescendo."],["iofh55s0o","Describe the murmur of mitral regurgitation.","Holosystolic, high-pitched blowing murmur at the apex radiating to the axilla.","Holossistólico no ápice."],["axyrgx1j9","Describe the murmur of tricuspid regurgitation.","Holosystolic, high-pitched blowing murmur at the left lower sternal border, louder with inspiration, radiating to right sternal border.","Holossistólico na borda esquerda."],["1nqw6bq1t","Describe the murmur of a ventricular septal defect.","Holosystolic, harsh murmur loudest at the tricuspid area (left lower sternal border).","Holossistólico rude."],["1d79byv1n","Describe the murmur of mitral valve prolapse.","Late systolic crescendo murmur with a midsystolic click (chordae tendineae tensing); best at apex.","Clique mesossistólico."],["17rirj8nm","Describe the murmur of aortic regurgitation.","High-pitched blowing early diastolic decrescendo murmur at the left sternal border; wide pulse pressure.","Diastólico em decrescendo."],["mrim8j1xb","Describe the murmur of mitral stenosis.","Opening snap followed by mid-to-late rumbling diastolic murmur at the apex.","Estalido e ruflar."],["1cvl2fgu1","What does a shorter interval between S2 and the opening snap in mitral stenosis indicate?","More severe mitral stenosis (higher left atrial pressure).","Estenose mais grave."],["1otm5ynjm","Describe the murmur of patent ductus arteriosus.","Continuous machine-like murmur, best at the left infraclavicular area, loudest at S2.","Sopro em maquinaria."],["ql6s6q10s","What causes bounding pulses and head bobbing?","Severe aortic regurgitation (wide pulse pressure).","Regurgitação aórtica."],["4bpe69145","What is pulsus paradoxus?","Decrease in systolic BP >10 mmHg during inspiration; seen in cardiac tamponade, severe asthma, COPD, constrictive pericarditis.","PA cai mais de 10 na inspiração."],["ped6hd1fw","What is pulsus parvus et tardus?","Weak and delayed carotid upstroke in aortic stenosis.","Pulso fraco e tardio."],["19oyqh61o","What is pulsus alternans?","Alternating strong and weak pulses; seen in severe left ventricular systolic dysfunction.","Força alternada."],["1mff51o17","What is a bisferiens pulse?","Double-peaked pulse seen in aortic regurgitation or hypertrophic cardiomyopathy.","Pulso com dois picos."],["1dlrxhsky","What is the shape of the pressure-volume loop?","A rectangle-like loop: bottom = filling, right side = isovolumetric contraction, top = ejection, left side = isovolumetric relaxation.","Retangular."],["zaovdh171","How does increased preload change the pressure-volume loop?","Wider loop (increased EDV and stroke volume).","Mais volume."],["1nbtj9y1u","How does increased afterload change the pressure-volume loop?","Taller and narrower loop (higher aortic pressure, decreased stroke volume, increased ESV).","Pressão maior, menos volume."],["10ptnxjqn","How does increased contractility change the pressure-volume loop?","Wider loop shifted left (decreased ESV, increased stroke volume).","Mais volume ejetado."],["1mov5qq1w","How does aortic stenosis appear on a PV loop?","High LV systolic pressure, decreased stroke volume.","Pressão sistólica alta."],["77uju0sbz","How does aortic regurgitation appear on a PV loop?","No true isovolumetric relaxation; increased EDV and stroke volume.","Sem relaxamento isovolumétrico."],["yurw3p16t","How does mitral regurgitation appear on a PV loop?","No true isovolumetric contraction; increased EDV, decreased ESV in early stages.","Sem contração isovolumétrica."],["1yv4f331d","How does mitral stenosis appear on a PV loop?","Increased LA pressure, decreased EDV, decreased stroke volume.","Pressão de enchimento alta."],["1knzl281i","What is the ventricular function curve vs vascular function curve?","Cardiac output (cardiac function curve) and venous return (vascular function curve) plotted against right atrial pressure; intersection = operating point.","Débito cardíaco vs retorno venoso."],["1hihked80","What does a positive inotrope do to the cardiac and vascular function curves?","Shifts the cardiac function curve up; operating point moves to higher CO and lower RAP.","Débito cardíaco aumenta."],["1csc8661p","What does increased blood volume do to the vascular function curve?","Shifts the venous return curve right (higher mean systemic pressure), increasing CO and RAP.","Curva desloca para direita."],["1fivgfg11","What does decreased TPR do to the vascular function curve?","Rotates the venous return curve upward (more venous return at a given RAP), increasing CO.","Curva gira para cima."],["1uayjzc5a","What is mean systemic filling pressure?","The pressure in the vasculature when cardiac output is zero; determined by blood volume and venous tone.","Pressão sem fluxo."],["1vh21k4w3","What is end-diastolic volume normally?","About 120-140 mL in adults.","120 mL."],["rz2y7p1f8","What is the normal LV pressure in systole and diastole?","Systole about 120 mmHg, diastole about 0-10 mmHg.","120/10."],["1akmwkg1m","What is a normal pulmonary capillary wedge pressure and what does it estimate?","6-12 mmHg; estimates left atrial pressure.","6-12; átrio esquerdo."],["jx0u32p21","Which condition causes PCWP to overestimate LV end-diastolic pressure?","Mitral stenosis (left atrial pressure is higher than LVEDP).","Estenose mitral."],["1smx5h4bc","What does a Swan-Ganz catheter measure?","Right heart pressures, pulmonary artery pressure, PCWP, cardiac output (thermodilution), mixed venous O2.","Pressões direitas e cunha."],["vhyh0dtk5","What is the effect of aortic valve stenosis on myocardial O2 demand?","Increases demand (high afterload and hypertrophy), can cause angina even without coronary disease.","Aumenta."],["13tuke613","Why do patients with aortic stenosis faint on exertion?","Fixed cardiac output cannot increase to meet peripheral vasodilation during exercise.","Débito fixo."],["1g9r86ou8","What is the typical triad of severe aortic stenosis?","Syncope, angina, dyspnea (heart failure). SAD.","Angina, síncope, IC."],["t7i3yf1q3","What is the significance of an S3 in heart failure?","Indicates volume overload and elevated filling pressures; associated with dilated ventricle.","Sobrecarga de volume."],["swh89k8l9","What is the relationship of end-systolic volume to contractility?","Higher contractility lowers ESV.","Inversa."],["3gtpc2i8s","How does sympathetic stimulation affect heart rate and contractility?","Increases both (beta1: chronotropy, inotropy, dromotropy, lusitropy).","Aumenta ambos."],["1jfrvqhbi","What does lusitropy mean?","Rate of myocardial relaxation; increased by sympathetic stimulation via phospholamban phosphorylation (SERCA activity).","Relaxamento."],["163c26bwd","What protein, when phosphorylated, increases SERCA activity?","Phospholamban.","Fosfolambam."],["1kkq0ej1s","What is the role of the ryanodine receptor in cardiac muscle?","Releases Ca2+ from the sarcoplasmic reticulum in response to Ca2+ entry through L-type channels (calcium-induced calcium release).","Libera cálcio."],["6mhswjrc0","How does cardiac muscle contraction differ from skeletal muscle?","Cardiac relies on extracellular Ca2+ entry (calcium-induced calcium release), has gap junctions, and is not tetanizable.","Cálcio extracelular."],["12ehgi6wn","Why can't cardiac muscle undergo tetany?","Long refractory period (plateau phase) prevents summation.","Período refratário longo."],["rggddm1oz","What is the main determinant of coronary blood flow during exercise?","Local metabolites (adenosine, NO, CO2, H+) causing vasodilation.","Metabólitos locais."],["16se4z61o","Why are aortic stenosis murmurs louder after a pause (post-PVC)?","Longer filling increases stroke volume and gradient (unlike HCM where post-PVC pulse may weaken).","Mais enchimento."]]},{"name":"Physiology (Part 2)","cards":[["1x8iqk8gp","What happens in phase 0 of the ventricular action potential?","Rapid upstroke and depolarization: voltage-gated Na+ channels open.","Entrada rápida de sódio."],["w5xoe510i","What happens in phase 1 of the ventricular action potential?","Initial repolarization: inactivation of Na+ channels and opening of voltage-gated K+ channels.","Saída inicial de potássio."],["1pwlfha51","What happens in phase 2 of the ventricular action potential?","Plateau: Ca2+ influx through L-type channels balances K+ efflux; Ca2+ triggers SR Ca2+ release and contraction.","Platô de cálcio."],["cuvnunx3u","What happens in phase 3 of the ventricular action potential?","Rapid repolarization: massive K+ efflux through delayed rectifier channels; L-type Ca2+ channels close.","Repolarização por potássio."],["g54a54mol","What happens in phase 4 of the ventricular action potential?","Resting potential: high K+ permeability through inward rectifier K+ channels.","Repouso."],["11z02p8g3","Which cardiac cells have the ventricular-type (fast response) action potential?","Atrial myocytes, ventricular myocytes, Purkinje fibers.","Átrios, ventrículos, Purkinje."],["1hbjnda13","How does the pacemaker (SA/AV node) action potential differ in phase 0?","Upstroke is due to opening of voltage-gated L-type Ca2+ channels (slow), not Na+ channels.","Cálcio, não sódio."],["fnvn851fy","Which phases are absent in the pacemaker action potential?","Phases 1 and 2.","Fases 1 e 2."],["hd81ty1dk","What causes phase 4 slow diastolic depolarization in pacemaker cells?","Funny current (If): HCN channels open on hyperpolarization, allowing slow Na+ influx.","Corrente funny de sódio."],["1midr7t1c","How do sympathetic and parasympathetic stimulation alter heart rate?","Sympathetic increases the slope of phase 4 (faster rate); parasympathetic (ACh) decreases the slope and hyperpolarizes (slower rate).","Simpático acelera; vago freia."],["1lnplo31w","Which drug blocks the funny current to lower heart rate?","Ivabradine (used in heart failure with reduced EF).","Ivabradina."],["1bhkgcq9e","What is the effective refractory period?","Period during which another action potential cannot be generated, mainly phases 1-3.","Sem novo disparo."],["i1sd8dzpb","What does the P wave represent?","Atrial depolarization.","Despolarização atrial."],["1j8g89p3q","What does the PR interval represent and its normal duration?","Time from atrial depolarization to ventricular depolarization (AV node conduction); normally 120-200 ms.","Atraso no nó AV; menos de 200 ms."],["19pbgggp5","What does the QRS complex represent and its normal duration?","Ventricular depolarization; normally less than 120 ms.","Despolarização ventricular; menos de 120 ms."],["13niwlu13","What does the QT interval represent?","Ventricular depolarization, mechanical contraction, and repolarization.","Despolarização e repolarização."],["1whjt2xf3","What does the T wave represent?","Ventricular repolarization.","Repolarização ventricular."],["a302mw1bv","What does a U wave suggest?","Hypokalemia (or bradycardia).","Hipocalemia."],["hkf2i41n4","What does the ST segment represent?","Isoelectric period when the ventricles are depolarized.","Ventrículo despolarizado."],["1n8pohg8y","Why is atrial repolarization not seen on ECG?","It is masked by the QRS complex.","Escondida no QRS."],["zwajuvwpc","What does a peaked T wave suggest?","Hyperkalemia.","Hipercalemia."],["wc7bzt1ll","What ECG changes occur with progressive hyperkalemia?","Peaked T waves, PR prolongation, loss of P waves, wide QRS, sine wave pattern, ventricular fibrillation.","T apiculada, QRS largo, sine wave."],["4w0p651dr","What ECG change occurs with hypocalcemia?","Prolonged QT interval.","QT longo."],["1tlq6phus","What ECG change occurs with hypercalcemia?","Shortened QT interval.","QT curto."],["yuk4vs1s5","What is torsades de pointes?","Polymorphic ventricular tachycardia with shifting QRS axis, preceded by long QT; can progress to ventricular fibrillation.","TV polimórfica."],["y4zryddu7","Treatment of torsades de pointes?","IV magnesium sulfate; correct electrolytes; overdrive pacing; defibrillation if unstable.","Magnésio."],["1fmai3pvp","Which drug classes cause QT prolongation?","Antiarrhythmics (IA, III), antibiotics (macrolides, fluoroquinolones), antipsychotics (haloperidol), antidepressants (TCAs), antiemetics (ondansetron), methadone. ABCDE.","Antiarrítmicos, antibióticos, antipsicóticos."],["1jy8bkeuw","What is congenital long QT syndrome?","Inherited ion channel defects (often K+ channels) causing prolonged repolarization and risk of sudden death.","Canais iônicos defeituosos."],["1112nqahf","What is Romano-Ward syndrome?","Autosomal dominant congenital long QT syndrome without deafness.","QT longo sem surdez."],["1ehqwn41c","What is Jervell and Lange-Nielsen syndrome?","Autosomal recessive congenital long QT with sensorineural deafness.","QT longo com surdez."],["9k0c551hr","What is Brugada syndrome?","Autosomal dominant Na+ channelopathy, more common in Asian males; pseudo-right bundle branch block with ST elevation in V1-V2; risk of sudden death; treated with ICD.","Supra em V1-V3."],["jcjw41cdk","What is Wolff-Parkinson-White syndrome?","Accessory conduction pathway (bundle of Kent) bypasses the AV node, causing ventricular pre-excitation.","Via acessória."],["8b7gb8wcz","ECG findings of WPW?","Delta wave (slurred upstroke of QRS), widened QRS, shortened PR interval.","Onda delta, PR curto."],["1wtmb41dz","What arrhythmia is associated with WPW?","AV reentrant tachycardia; atrial fibrillation with rapid ventricular rate can be life-threatening.","Taquicardia reentrante."],["8mcm3b17z","Which drugs should be avoided in WPW with atrial fibrillation?","AV nodal blockers (adenosine, beta-blockers, calcium channel blockers, digoxin), which may increase conduction through the accessory pathway.","Bloqueadores do nó AV."],["1yh5j9oq5","ECG findings of atrial fibrillation?","Irregularly irregular rhythm without discrete P waves.","Irregular sem P."],["1ogge0f1b","ECG findings of atrial flutter?","Rapid identical sawtooth flutter waves (often 300/min) with fixed or variable AV block (e.g., 2:1 giving 150 bpm).","Dente de serra."],["8wf22p9jv","Definitive treatment of typical atrial flutter?","Catheter ablation of the cavotricuspid isthmus.","Ablação."],["1we7zf819","ECG findings of ventricular fibrillation?","Erratic, disorganized waveform without identifiable waves; fatal without immediate CPR and defibrillation.","Caótico, sem QRS."],["7aztlj1d7","What is first-degree AV block?","Prolonged PR interval (>200 ms) that is constant; benign, usually asymptomatic.","PR maior que 200 ms."],["kyurarqsb","What is Mobitz type I (Wenckebach) second-degree AV block?","Progressive PR lengthening until a beat is dropped; usually benign and at the AV node level.","PR aumenta até falhar."],["jvmt0iv3a","What is Mobitz type II second-degree AV block?","Dropped beats without prior PR change; usually infranodal (His-Purkinje); can progress to third-degree block; treat with pacemaker.","Falha súbita sem aviso."],["1384f7qce","What is third-degree (complete) AV block?","Atria and ventricles beat independently; P waves and QRS have no relationship; atrial rate faster than ventricular rate.","Átrios e ventrículos dissociados."],["1x6wx8z1j","Treatment of third-degree AV block?","Pacemaker.","Marcapasso."],["psigm71sq","What infection can cause third-degree heart block?","Lyme disease.","Doença de Lyme."],["lalrrzbw2","What is the role of arterial baroreceptors?","Sense blood pressure changes in the carotid sinus and aortic arch and adjust autonomic output to maintain BP.","Controlar pressão."],["lnvg3m1hn","Which nerves carry the carotid sinus and aortic arch baroreceptor signals?","Carotid sinus: glossopharyngeal nerve (CN IX). Aortic arch: vagus nerve (CN X).","Glossofaríngeo e vago."],["10rciaa5b","What does the aortic arch baroreceptor respond to?","Only increases in blood pressure.","Só pressão alta."],["19ttx811c","What does the carotid sinus baroreceptor respond to?","Increases and decreases in blood pressure.","Pressão alta e baixa."],["1wyby6yy4","What is the response to hypotension via baroreceptors?","Decreased firing leads to increased sympathetic and decreased parasympathetic output: vasoconstriction, increased HR, contractility, and BP.","Simpático aumenta."],["1be2jnu1f","What happens with carotid massage?","Increased carotid sinus stretch increases afferent firing, increasing vagal tone and decreasing HR (can terminate SVT).","Bradicardia."],["1l2uu7y1c","What is the Cushing reflex?","Triad of hypertension, bradycardia, and respiratory depression in response to increased intracranial pressure.","Hipertensão, bradicardia, respiração irregular."],["ewnf4smdw","Mechanism of the Cushing reflex?","Increased ICP compresses arterioles causing CNS ischemia, raising sympathetic output (hypertension); baroreceptors then cause reflex bradycardia.","Isquemia cerebral."],["qluuv2emc","Where are peripheral chemoreceptors and what do they sense?","Carotid and aortic bodies; respond to decreased PaO2 (<60 mmHg), increased PaCO2, decreased pH.","Carótida e aorta; O2 baixo."],["1ri6eqp8b","What do central chemoreceptors sense?","Changes in pH and PCO2 of brain interstitial fluid (CO2 diffuses across the blood-brain barrier).","pH e CO2."],["hn5cg2acq","Which organ receives the largest share of systemic cardiac output?","Liver (via portal and hepatic circulation), followed by kidneys.","Fígado."],["fbzu2nwl5","Which organ has the highest blood flow per gram of tissue?","Kidney.","Rim."],["tnv60612y","Which organ has the largest arteriovenous O2 difference at rest?","Heart (extracts about 80% of O2); increased demand requires increased coronary flow.","Coração."],["1bc01ls1k","What is autoregulation of blood flow?","The ability of an organ to maintain constant blood flow despite changes in perfusion pressure.","Fluxo constante."],["1mo9oem11","What mainly controls cerebral blood flow?","Local metabolites, especially PCO2 (and PO2 when very low).","CO2."],["1glnlztp8","Why does hyperventilation reduce intracranial pressure?","Decreased PCO2 causes cerebral vasoconstriction, reducing cerebral blood volume.","CO2 baixo vasoconstringe."],["d9t4a1170","What controls coronary blood flow?","Local metabolites (adenosine, NO, CO2, low O2).","Metabólitos locais."],["11cyp1vc8","What controls pulmonary blood flow?","Hypoxic vasoconstriction diverts blood away from poorly ventilated areas.","Hipóxia vasoconstringe."],["1cqvjom18","What controls skeletal muscle blood flow at rest vs exercise?","At rest: sympathetic tone (alpha1). During exercise: local metabolites (lactate, adenosine, K+, H+, CO2).","Simpático vs metabólitos."],["1bnlryb1j","What controls skin blood flow?","Sympathetic stimulation for temperature control.","Temperatura."],["1v191w31v","What controls renal blood flow autoregulation?","Myogenic response (afferent arteriole) and tubuloglomerular feedback.","Miogênica e túbulo-glomerular."],["1hy3rcmhg","What are the Starling forces governing capillary fluid exchange?","Capillary hydrostatic pressure (Pc), interstitial hydrostatic pressure (Pi), capillary oncotic pressure (πc), interstitial oncotic pressure (πi).","Pressões hidrostática e oncótica."],["1m7d2wv10","What is the net filtration pressure formula?","Pnet = [(Pc - Pi) - (πc - πi)]; Jv = Kf x Pnet.","Kf x forças."],["1vr5m5b1w","What causes edema according to Starling forces?","Increased capillary pressure (heart failure), decreased plasma proteins (nephrotic syndrome, liver failure), increased capillary permeability (burns, toxins), increased interstitial oncotic pressure (lymphatic blockage).","Desequilíbrio das forças."],["1rshw941t","Why does liver cirrhosis cause edema?","Decreased albumin synthesis lowers plasma oncotic pressure (plus portal hypertension).","Albumina baixa."],["1715yia10","What is the response to standing up quickly?","Blood pools in the legs, decreasing venous return and CO; baroreceptors trigger increased sympathetic output to restore BP.","Simpático compensa."],["19gyzrqu1","What is orthostatic hypotension?","Drop in systolic BP ≥20 or diastolic BP ≥10 mmHg within 3 minutes of standing.","Queda ao levantar."],["ug4g788dk","What are the effects of the Valsalva maneuver on blood pressure?","Phase II: decreased venous return lowers stroke volume and BP, causing reflex tachycardia; phase IV: BP overshoot with reflex bradycardia.","Pressão cai e sobe."],["1z07k57v3","What are the cardiovascular effects of exercise?","Increased HR, stroke volume, CO, systolic BP; decreased TPR (vasodilation in muscles); diastolic BP stable or decreased.","Débito aumenta."],["uz2esh316","What is the effect of hemorrhage on hemodynamics?","Decreased preload and CO with increased TPR (sympathetic vasoconstriction) and HR; compensated until about 15-30% volume loss.","Débito cai."],["1t9f5x91e","What are the hemodynamic parameters in hypovolemic shock?","Decreased CO, decreased PCWP, increased SVR.","Débito baixo, RVP alta."],["1kxufu81d","What are the hemodynamic parameters in cardiogenic shock?","Decreased CO, increased PCWP, increased SVR.","Débito baixo, cunha alta."],["1zu46t1b2","What are the hemodynamic parameters in septic (distributive) shock?","Increased CO (early), decreased PCWP, decreased SVR; warm extremities.","Débito alto, RVP baixa."],["8yeevperr","What are the hemodynamic parameters in obstructive shock (tamponade, PE)?","Decreased CO, variable PCWP (increased in tamponade), increased SVR.","Débito baixo, PVC alta."],["1utlyywxd","How does neurogenic shock differ from other shock?","Decreased sympathetic tone leads to hypotension with bradycardia and warm, dry skin.","Sem taquicardia."],["msbgcm1ur","What is the normal right atrial pressure?","About 0-5 mmHg (<5 mmHg).","Menos de 5."],["1ohprvi1f","What is the normal right ventricular pressure?","About 25/5 mmHg.","25/5."],["qe3lr71nu","What is the normal pulmonary artery pressure?","About 25/10 mmHg.","25/10."],["12kjtb91w","What is the normal left ventricular pressure?","About 130/10 mmHg.","130/10."],["ji28ywqvq","What is the major determinant of myocardial oxygen supply?","Coronary blood flow (mainly in diastole) and O2 content.","Fluxo diastólico."],["so8u6x169","Why does tachycardia worsen ischemia?","Increases O2 demand and shortens diastole, reducing coronary perfusion time.","Encurta diástole."],["1urwra81n","What is the role of nitric oxide in vascular tone?","Endothelium-derived relaxing factor; activates guanylyl cyclase, increasing cGMP and smooth muscle relaxation.","Vasodilatação."],["1q3li8s13","What is the role of endothelin?","Potent vasoconstrictor produced by endothelium; antagonists (bosentan) treat pulmonary arterial hypertension.","Vasoconstrição."],["11u5pztwy","What does ANP do?","Released by atria in response to increased volume/stretch; causes vasodilation, natriuresis, decreased renin; acts via cGMP.","Diurese e vasodilatação."],["1lwo8lf1m","What does BNP do and what is its clinical use?","Released from ventricles in response to stretch; similar actions to ANP; high levels in heart failure (diagnostic); nesiritide is recombinant BNP.","Marcador de IC."],["1t0i2hd1u","How does angiotensin II raise blood pressure?","Vasoconstriction (AT1), aldosterone release, ADH release, increased thirst, increased sympathetic tone, efferent arteriole constriction.","Vasoconstrição e aldosterona."],["1uan1xoaz","What triggers renin release?","Decreased renal perfusion (afferent arteriole baroreceptors), decreased NaCl at macula densa, sympathetic beta1 stimulation.","Pressão baixa no rim."],["13tr95l3l","How does ADH raise blood pressure?","V1 receptors cause vasoconstriction; V2 receptors increase water reabsorption in the collecting duct.","Vasoconstrição e água."],["638m5h1jt","What is the effect of sympathetic alpha1 activation on vessels?","Vasoconstriction (increases TPR).","Vasoconstrição."],["giyry01b9","What is the effect of beta2 activation on skeletal muscle arterioles?","Vasodilation.","Vasodilatação."],["tcvsvldme","What is the role of lymphatics in fluid balance?","Return excess interstitial fluid and proteins to the circulation; obstruction causes lymphedema.","Devolvem líquido."],["13tvw0ly2","How does a ventricular premature beat appear on ECG?","Wide, bizarre QRS without a preceding P wave, often followed by a compensatory pause.","QRS largo precoce."],["1sbblox18","What is sinus arrhythmia?","Normal variation of heart rate with breathing (faster on inspiration), common in young people.","FC varia com respiração."],["5brixh1ib","What is the mean electrical axis normal range?","-30 to +90 degrees.","-30 a +90."],["v235yxba6","What causes left axis deviation?","Left anterior fascicular block, LV hypertrophy, inferior MI.","Hipertrofia de VE, bloqueio."],["17wu4oy1q","What causes right axis deviation?","Right ventricular hypertrophy, left posterior fascicular block, lateral MI, pulmonary hypertension.","Hipertrofia de VD, TEP."],["1b1su8n10","What ECG finding indicates right bundle branch block?","Wide QRS with rSR' in V1 (rabbit ears) and wide S wave in V6.","rSR' em V1."],["nl2guk17y","What ECG finding indicates left bundle branch block?","Wide QRS with broad notched R in V6 and deep S in V1.","QRS largo em V6."],["1wr93h7tq","Which acute coronary event can cause new left bundle branch block?","Acute anterior MI (LAD occlusion).","Isquemia anterior."]]}];
